INSERT INTO `blog_posts` (`id`, `author_id`, `title`, `slug`, `excerpt`, `content`, `category_id`, `category`, `cover_image_path`, `cover_image_alt`, `status`, `is_featured`, `published_at`, `content_updated_at`, `primary_keyword`, `related_keywords`, `meta_title`, `meta_description`, `canonical_url`, `social_image_path`, `should_index`, `created_at`, `updated_at`) VALUES
(1, NULL, 'Como calcular honorários contábeis sem perder rentabilidade', 'como-calcular-honorarios-contabeis', 'Aprenda a formar honorários contábeis considerando regime tributário, volume de trabalho, complexidade, risco e margem desejada.', '<p>Aprenda a formar honorários contábeis considerando regime tributário, volume de trabalho, complexidade, risco e margem desejada.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>Por que copiar a mensalidade do concorrente é arriscado</h2><p>O preço de um serviço contábil precisa remunerar horas técnicas, estrutura, tecnologia, responsabilidade profissional e risco. Quando o escritório replica valores de mercado sem conhecer sua própria operação, pode conquistar clientes que aumentam o faturamento e, ao mesmo tempo, reduzem a margem. A precificação sustentável começa pela realidade do escritório e depois é confrontada com o posicionamento desejado.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Mapeie o custo mensal de atendimento</h2><p>Liste o tempo previsto para escrituração, fiscal, folha, obrigações acessórias, atendimento, revisão e gestão. Some custos diretos, rateio de equipe, sistemas, certificados, armazenamento, estrutura e tributos do próprio escritório. Transforme esse total em custo por hora produtiva e considere que nem todas as horas contratadas são faturáveis.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Ajuste pelo perfil e pela complexidade do cliente</h2><p>Regime tributário, quantidade de funcionários, número de documentos, diversidade de operações, filiais, comércio exterior, retenções, substituição tributária e qualidade das informações mudam o esforço necessário. Clientes com atraso recorrente, documentos desorganizados ou elevado risco fiscal exigem uma reserva maior de capacidade.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Inclua margem, risco e escopo</h2><p>Depois de estimar o custo, aplique a margem necessária para financiar crescimento, treinamento, suporte e imprevistos. Registre claramente o que está incluído, limites de movimentação, serviços extraordinários e critérios de reajuste. Um preço bem explicado tende a ser melhor aceito do que um número apresentado sem contexto.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Revise periodicamente</h2><p>Reavalie honorários quando houver mudança de regime, aumento de faturamento, contratação de funcionários, abertura de filial ou crescimento do volume documental. A revisão periódica evita que o contrato permaneça defasado enquanto o trabalho cresce silenciosamente.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-de-honorarios-contabeis\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>Existe uma tabela única de honorários contábeis?</h3><p>Não existe um valor nacional que represente todos os escritórios e clientes. Referências regionais podem ajudar, mas o preço final precisa refletir custo, escopo, risco e posicionamento.</p><h3>Devo cobrar por faturamento ou por volume?</h3><p>Os dois indicadores podem ser usados, mas nenhum deve ser isolado. O ideal é combinar porte, volume operacional, complexidade e esforço estimado.</p><h3>Quando reajustar o contrato?</h3><p>Além do reajuste periódico previsto em contrato, revise quando houver alteração relevante no perfil operacional do cliente.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 1, 'Gestão Contábil', 'blog/covers/como-calcular-honorarios-contabeis.png', 'Ilustração do guia: Como calcular honorários contábeis sem perder rentabilidade', 'published', 1, '2026-07-13 12:00:00', '2026-07-13 12:00:00', 'como calcular honorários contábeis', '[\"precificação contábil\", \"tabela de honorários contábeis\", \"valor mensalidade contabilidade\", \"custos do escritório contábil\"]', 'Como calcular honorários contábeis sem perder rentabilidade', 'Como calcular honorários contábeis com critérios objetivos, margem sustentável e ajustes por porte, regime e complexidade do cliente.', NULL, 'blog/social/como-calcular-honorarios-contabeis.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(2, NULL, 'Como validar CNPJ, CPF e inscrição estadual antes do cadastro', 'como-validar-cnpj-cpf-inscricao-estadual', 'Veja como identificar erros de digitação, dígitos verificadores inválidos e inconsistências cadastrais antes de importar ou registrar dados.', '<p>Veja como identificar erros de digitação, dígitos verificadores inválidos e inconsistências cadastrais antes de importar ou registrar dados.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>Validação sintática não é consulta cadastral</h2><p>A validação do número confirma formato e dígitos verificadores. Ela elimina muitos erros de digitação, mas não prova que o cadastro está ativo, pertence à pessoa informada ou está regular perante órgãos públicos. Para decisões de risco, combine a validação matemática com fontes oficiais e documentos comprobatórios.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Por que validar antes de importar</h2><p>Um documento incorreto pode contaminar cadastros, notas, obrigações acessórias, relatórios e integrações. Corrigir o erro na entrada custa menos do que localizar o mesmo problema depois que ele se espalhou por diferentes sistemas.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Como tratar arquivos em lote</h2><p>Ao validar planilhas ou arquivos tabulares, preserve a linha original, normalize pontuação apenas para o cálculo e produza um relatório com valor informado, valor normalizado e motivo da rejeição. Não altere automaticamente números duvidosos; encaminhe-os para revisão.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Cuidados com inscrição estadual</h2><p>As regras da inscrição estadual variam por unidade federativa e podem ter tamanhos e algoritmos diferentes. Por isso, a UF é parte essencial da validação. Um número matematicamente válido para um estado não deve ser aceito como se fosse de outro.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Proteção de dados</h2><p>CPF e outros identificadores pessoais exigem finalidade, controle de acesso e retenção adequada. Evite incluir documentos completos em logs, URLs, capturas de tela ou arquivos de teste sem necessidade.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/validador-de-cnpj\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>Um CNPJ válido está necessariamente ativo?</h3><p>Não. A validação dos dígitos não substitui a consulta da situação cadastral em fonte oficial.</p><h3>É seguro remover pontos e traços?</h3><p>Sim para normalização técnica, desde que o valor original seja preservado quando necessário para auditoria.</p><h3>Toda inscrição estadual tem a mesma regra?</h3><p>Não. Cada UF pode adotar formato e algoritmo próprios.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 2, 'Cadastros e Validações', 'blog/covers/como-validar-cnpj-cpf-inscricao-estadual.png', 'Ilustração do guia: Como validar CNPJ, CPF e inscrição estadual antes do cadastro', 'published', 1, '2026-07-14 12:00:00', '2026-07-14 12:00:00', 'validar CNPJ CPF inscrição estadual', '[\"validador de CNPJ\", \"consulta CPF\", \"validação inscrição estadual\", \"documentos cadastrais\"]', 'Como validar CNPJ, CPF e inscrição estadual antes do cadastro', 'Valide CNPJ, CPF e inscrição estadual antes do cadastro e reduza erros em documentos fiscais, integrações e rotinas contábeis.', NULL, 'blog/social/como-validar-cnpj-cpf-inscricao-estadual.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(3, NULL, 'DARF e GPS: como conferir código, vencimento, juros e multa', 'como-gerar-darf-gps-codigo-vencimento-acrescimos', 'Entenda os dados que precisam ser revisados antes de emitir DARF ou GPS e como documentar a memória de cálculo dos acréscimos.', '<p>Entenda os dados que precisam ser revisados antes de emitir DARF ou GPS e como documentar a memória de cálculo dos acréscimos.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>Comece pela obrigação correta</h2><p>A emissão da guia depende da natureza do débito, período de apuração, contribuinte e código de receita. Um código incorreto pode direcionar o pagamento para obrigação diferente e gerar pendência mesmo quando o valor foi recolhido.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Confirme período e vencimento</h2><p>Competência, período de apuração e data de vencimento não são campos equivalentes. Feriados e regras específicas também podem alterar a data efetiva. Registre a base normativa e a data de referência usada na geração.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Acréscimos por atraso</h2><p>Quando houver atraso, a memória deve separar principal, multa e juros. O cálculo precisa considerar a regra aplicável ao tributo e a data prevista de pagamento. Evite lançar apenas o total: a decomposição facilita revisão e conciliação.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Dados do contribuinte</h2><p>Revise CPF ou CNPJ, nome, identificação do débito, código, referência e valor. Em rotinas com muitos clientes, use dupla conferência ou validações automatizadas antes da emissão definitiva.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Guarde evidências</h2><p>Salve a memória de cálculo, parâmetros, data de geração e responsável pela revisão. Isso reduz retrabalho quando o cliente pergunta como o valor foi formado ou quando ocorre divergência na baixa do pagamento.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/gerador-darf-gps\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>DARF e GPS são a mesma guia?</h3><p>Não. São documentos distintos e atendem obrigações específicas.</p><h3>Posso usar qualquer código de receita parecido?</h3><p>Não. O código precisa corresponder exatamente à obrigação e ao enquadramento do débito.</p><h3>Como evitar divergência de juros?</h3><p>Use a data real de pagamento, a regra aplicável e preserve a memória de cálculo para conferência.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 3, 'Fiscal e Tributário', 'blog/covers/como-gerar-darf-gps-codigo-vencimento-acrescimos.png', 'Ilustração do guia: DARF e GPS: como conferir código, vencimento, juros e multa', 'published', 1, '2026-07-15 12:00:00', '2026-07-15 12:00:00', 'como gerar DARF e GPS', '[\"código DARF\", \"vencimento DARF\", \"juros e multa DARF\", \"guia GPS\"]', 'DARF e GPS: como conferir código, vencimento, juros e multa', 'Confira código, período, vencimento, multa e juros antes de gerar DARF ou GPS e mantenha uma memória de cálculo auditável.', NULL, 'blog/social/como-gerar-darf-gps-codigo-vencimento-acrescimos.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(4, NULL, 'Como converter XML de NF-e e NFC-e em planilha com segurança', 'como-converter-xml-nfe-nfce-planilha', 'Aprenda a extrair produtos, NCM, CFOP, impostos e totais de arquivos XML sem perder rastreabilidade nem misturar documentos inválidos.', '<p>Aprenda a extrair produtos, NCM, CFOP, impostos e totais de arquivos XML sem perder rastreabilidade nem misturar documentos inválidos.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>O XML é a fonte estruturada</h2><p>O PDF auxiliar facilita a leitura humana, mas o XML contém os campos estruturados usados em validações e integrações. Para análise em lote, prefira o XML autorizado e preserve o arquivo original junto ao resultado.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Defina a granularidade da planilha</h2><p>Uma nota pode gerar uma linha de cabeçalho e várias linhas de itens. Antes de exportar, decida se a análise será por documento, produto ou tributo. Misturar granularidades em uma única tabela costuma causar duplicidade de totais.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Campos importantes</h2><p>Chave de acesso, emitente, destinatário, data, modelo, série, número, CFOP, NCM, CST ou CSOSN, valores de produtos, descontos, frete e tributos devem ser tratados com tipos adequados. Identificadores longos devem ser exportados como texto para não perder zeros ou precisão.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Validações de consistência</h2><p>Compare soma dos itens com totais, identifique XML duplicado, documento cancelado, campos ausentes e diferenças de arredondamento. Alertas não devem apagar dados; devem acompanhar a linha para revisão.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Segurança e retenção</h2><p>Arquivos fiscais podem conter dados comerciais e pessoais. Restrinja acesso, evite compartilhamentos públicos e defina política de retenção para originais e exportações.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/conversor-fiscal-xml\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>Posso converter o DANFE em vez do XML?</h3><p>O DANFE não substitui o XML e pode omitir estrutura necessária para uma extração confiável.</p><h3>Por que a chave aparece em notação científica no Excel?</h3><p>Porque planilhas podem interpretar identificadores longos como números. Exporte a chave como texto.</p><h3>Como tratar XML duplicado?</h3><p>Use a chave de acesso como referência e sinalize duplicidades sem descartar silenciosamente os arquivos.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 3, 'Fiscal e Tributário', 'blog/covers/como-converter-xml-nfe-nfce-planilha.png', 'Ilustração do guia: Como converter XML de NF-e e NFC-e em planilha com segurança', 'published', 0, '2026-07-16 12:00:00', '2026-07-16 12:00:00', 'converter XML NF-e para planilha', '[\"XML para Excel\", \"extrair dados XML NF-e\", \"converter NFC-e\", \"planilha de notas fiscais\"]', 'Como converter XML de NF-e e NFC-e em planilha com segurança', 'Converta XML de NF-e e NFC-e em planilha preservando produtos, NCM, CFOP, impostos, totais e alertas de consistência.', NULL, 'blog/social/como-converter-xml-nfe-nfce-planilha.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(5, NULL, 'Como calcular rescisão trabalhista passo a passo', 'como-calcular-rescisao-trabalhista', 'Confira as principais verbas da rescisão, os dados de entrada e os pontos que mudam conforme motivo do desligamento e datas do contrato.', '<p>Confira as principais verbas da rescisão, os dados de entrada e os pontos que mudam conforme motivo do desligamento e datas do contrato.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>O motivo do desligamento muda o cálculo</h2><p>Pedido de demissão, dispensa sem justa causa, justa causa, acordo e término de contrato produzem direitos diferentes. A primeira etapa é classificar corretamente o desligamento e registrar datas de admissão, comunicação e término.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Saldo de salário</h2><p>Calcule os dias trabalhados no mês da saída com base na regra aplicável ao salário mensal e considere adicionais habituais quando integrarem a remuneração. Faltas, adiantamentos e outras ocorrências precisam de documentação.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Férias e décimo terceiro</h2><p>Verifique períodos vencidos, proporcionais, faltas que afetam o direito, terço constitucional e avos do décimo terceiro. O tratamento de médias variáveis exige atenção às verbas e ao período de apuração.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Aviso-prévio e FGTS</h2><p>Defina se o aviso é trabalhado ou indenizado e considere a projeção quando aplicável. Depósitos de FGTS, multa rescisória e movimentação da conta dependem do tipo de desligamento.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Conferência final</h2><p>Separe proventos e descontos, registre as bases de INSS e IRRF e confronte o resultado com documentos do contrato. Uma memória detalhada facilita a revisão antes do pagamento e da transmissão dos eventos.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-de-rescisao\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>Toda rescisão tem multa de 40% do FGTS?</h3><p>Não. A incidência depende do motivo do desligamento.</p><h3>Aviso indenizado projeta o contrato?</h3><p>Em situações aplicáveis, a projeção repercute em datas e verbas; o caso deve ser conferido conforme a regra vigente.</p><h3>Férias vencidas e proporcionais são iguais?</h3><p>Não. Elas se referem a períodos diferentes e podem ter tratamentos distintos.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 4, 'Trabalhista', 'blog/covers/como-calcular-rescisao-trabalhista.png', 'Ilustração do guia: Como calcular rescisão trabalhista passo a passo', 'published', 0, '2026-07-17 12:00:00', '2026-07-17 12:00:00', 'como calcular rescisão trabalhista', '[\"cálculo de rescisão\", \"aviso prévio\", \"férias proporcionais\", \"multa FGTS\"]', 'Como calcular rescisão trabalhista passo a passo', 'Aprenda a calcular rescisão trabalhista com saldo salarial, férias, 13º, aviso-prévio, FGTS e descontos aplicáveis.', NULL, 'blog/social/como-calcular-rescisao-trabalhista.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(6, NULL, 'Margem e markup: como calcular o preço de venda corretamente', 'margem-markup-como-calcular-preco-venda', 'Entenda a diferença entre margem e markup e monte um preço de venda que cubra custos, despesas, tributos e lucro desejado.', '<p>Entenda a diferença entre margem e markup e monte um preço de venda que cubra custos, despesas, tributos e lucro desejado.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>Margem e markup não são sinônimos</h2><p>A margem mede o lucro em relação ao preço de venda. O markup é um multiplicador aplicado sobre uma base de custo. Usar o mesmo percentual nas duas abordagens gera resultados diferentes e pode deixar o preço abaixo do necessário.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Mapeie todos os componentes</h2><p>Considere custo de aquisição ou produção, frete, embalagem, comissões, taxas de meios de pagamento, tributos sobre venda, perdas e despesas variáveis. Custos fixos podem ser incorporados por rateio ou tratados na análise de ponto de equilíbrio.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Defina o lucro desejado</h2><p>O lucro deve ser definido sobre uma base clara. Para trabalhar com margem sobre venda, despesas percentuais e lucro disputam o mesmo preço final. Por isso, somar percentuais diretamente ao custo nem sempre alcança a margem pretendida.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Teste cenários</h2><p>Compare preço atual, preço calculado, volume esperado e sensibilidade a descontos. Um desconto aparentemente pequeno pode consumir grande parte do lucro quando a margem é estreita.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Revise com dados reais</h2><p>Depois de aplicar o preço, acompanhe custo efetivo, impostos, devoluções e comissões. A formação de preço é um processo contínuo, não um cálculo feito uma única vez.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-margem-markup\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>Markup de 50% significa margem de 50%?</h3><p>Não. Um custo de 100 com markup de 50% gera preço de 150 e margem bruta de aproximadamente 33,3%.</p><h3>Tributos entram no custo?</h3><p>Tributos incidentes sobre a venda normalmente precisam ser considerados na formação do preço, respeitando o regime e a operação.</p><h3>Posso usar a mesma margem para todos os produtos?</h3><p>Pode ser inadequado. Giro, risco, concorrência, perdas e capital empregado variam entre produtos e serviços.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 1, 'Gestão Contábil', 'blog/covers/margem-markup-como-calcular-preco-venda.png', 'Ilustração do guia: Margem e markup: como calcular o preço de venda corretamente', 'published', 0, '2026-07-18 12:00:00', '2026-07-18 12:00:00', 'como calcular margem e markup', '[\"calculadora de markup\", \"margem de lucro\", \"formação de preço\", \"preço de venda\"]', 'Margem e markup: como calcular o preço de venda corretamente', 'Entenda margem e markup e calcule um preço de venda que cubra custos, despesas, tributos e lucro sem confundir percentuais.', NULL, 'blog/social/margem-markup-como-calcular-preco-venda.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(7, NULL, 'Pró-labore e distribuição de lucros: como definir valores', 'pro-labore-distribuicao-lucros-como-definir', 'Veja como separar remuneração pelo trabalho e retorno do capital, estimar encargos e documentar a distribuição de lucros aos sócios.', '<p>Veja como separar remuneração pelo trabalho e retorno do capital, estimar encargos e documentar a distribuição de lucros aos sócios.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>São naturezas diferentes</h2><p>Pró-labore remunera o trabalho do sócio na empresa. Distribuição de lucros representa o retorno do resultado empresarial. Tratar toda retirada como lucro sem avaliar atividade, escrituração e resultado pode criar risco fiscal e previdenciário.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Definição do pró-labore</h2><p>A empresa deve observar função exercida, capacidade financeira, referências de mercado e regras previdenciárias. O valor precisa ser formalizado e processado com os encargos correspondentes, incluindo retenções quando aplicáveis.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Apuração dos lucros</h2><p>A distribuição depende de lucro efetivamente apurado e de suporte contábil. Balancetes, demonstrações, registros societários e separação entre patrimônio pessoal e empresarial fortalecem a evidência da operação.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Vários sócios</h2><p>Critérios de participação podem seguir quotas ou disposições societárias válidas. Quando as retiradas não acompanham a participação, documente a justificativa e verifique as condições legais e contratuais.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Simule antes de decidir</h2><p>Compare diferentes valores de pró-labore, encargos, caixa disponível e resultado acumulado. A simulação não substitui a análise jurídica e contábil, mas ajuda a identificar cenários inviáveis e dados ausentes.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-pro-labore-distribuicao-lucros\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>Sócio que trabalha precisa receber pró-labore?</h3><p>A situação deve ser analisada conforme atuação e regras aplicáveis; simplesmente classificar toda retirada como lucro pode ser inadequado.</p><h3>Lucro distribuído é sempre isento?</h3><p>A tributação depende do atendimento das condições legais e da comprovação do lucro.</p><h3>Posso distribuir lucro todo mês?</h3><p>É possível haver antecipações ou distribuições periódicas quando suportadas por apuração e documentação adequadas.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 3, 'Fiscal e Tributário', 'blog/covers/pro-labore-distribuicao-lucros-como-definir.png', 'Ilustração do guia: Pró-labore e distribuição de lucros: como definir valores', 'published', 0, '2026-07-19 12:00:00', '2026-07-19 12:00:00', 'pró-labore e distribuição de lucros', '[\"cálculo pró-labore\", \"INSS pró-labore\", \"IRRF pró-labore\", \"lucros isentos\"]', 'Pró-labore e distribuição de lucros: como definir valores', 'Entenda como definir pró-labore e distribuição de lucros, estimar INSS e IRRF e manter documentação contábil adequada.', NULL, 'blog/social/pro-labore-distribuicao-lucros-como-definir.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(8, NULL, 'Simples Nacional: como calcular DAS, alíquota efetiva e Fator R', 'simples-nacional-como-calcular-das-fator-r', 'Aprenda a usar receita acumulada, faixa, parcela a deduzir e Fator R para estimar o DAS com memória de cálculo.', '<p>Aprenda a usar receita acumulada, faixa, parcela a deduzir e Fator R para estimar o DAS com memória de cálculo.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>Identifique atividade e anexo</h2><p>O cálculo começa pelo enquadramento da receita no anexo adequado. Uma mesma empresa pode ter receitas sujeitas a tratamentos diferentes, por isso a segregação correta é tão importante quanto a fórmula.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Use a receita acumulada de doze meses</h2><p>A faixa é determinada pela receita bruta acumulada nos doze meses anteriores ao período de apuração. Empresas em início de atividade podem seguir regras de proporcionalização. Não confunda receita do mês com receita acumulada.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Alíquota efetiva</h2><p>A alíquota nominal da tabela não é aplicada isoladamente. A fórmula considera receita acumulada, alíquota nominal e parcela a deduzir. O resultado é a alíquota efetiva usada sobre a receita segregada do período.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Fator R</h2><p>Para determinadas atividades, a relação entre folha e receita acumuladas pode direcionar a tributação entre anexos. Folha, pró-labore e encargos devem ser apurados de forma consistente no período correspondente.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Memória e conferência</h2><p>Guarde anexo, faixa, receitas, folha, parcela a deduzir e resultado da alíquota. Compare a estimativa com o sistema oficial e investigue divergências de segregação, período ou classificação.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-simples-nacional\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>A alíquota da primeira faixa é sempre o percentual pago?</h3><p>A carga efetiva depende da fórmula e da composição da receita, embora na primeira faixa possa coincidir em situações simples.</p><h3>O que entra no Fator R?</h3><p>A composição deve seguir as regras vigentes para folha e receita no período considerado.</p><h3>Posso somar todas as receitas e aplicar uma única alíquota?</h3><p>Nem sempre. Receitas podem exigir segregações por atividade, anexo ou tratamento tributário.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 3, 'Fiscal e Tributário', 'blog/covers/simples-nacional-como-calcular-das-fator-r.png', 'Ilustração do guia: Simples Nacional: como calcular DAS, alíquota efetiva e Fator R', 'published', 0, '2026-07-20 12:00:00', '2026-07-20 12:00:00', 'como calcular Simples Nacional', '[\"calculadora Simples Nacional\", \"alíquota efetiva\", \"Fator R\", \"anexos Simples Nacional\"]', 'Simples Nacional: como calcular DAS, alíquota efetiva e Fator R', 'Calcule Simples Nacional com receita acumulada, faixa, alíquota efetiva, anexo e Fator R, entendendo cada etapa do DAS.', NULL, 'blog/social/simples-nacional-como-calcular-das-fator-r.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(9, NULL, 'Simples, Lucro Presumido ou Lucro Real: como comparar regimes', 'simples-lucro-presumido-lucro-real-comparacao', 'Veja quais premissas usar para comparar regimes tributários e por que faturamento isolado não é suficiente para decidir.', '<p>Veja quais premissas usar para comparar regimes tributários e por que faturamento isolado não é suficiente para decidir.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>Comparação exige premissas equivalentes</h2><p>Os regimes usam bases, períodos e tributos diferentes. Para comparar, aplique o mesmo horizonte de receita, atividade, folha, margem, despesas e localização. Resultados construídos com premissas diferentes não são comparáveis.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Simples Nacional</h2><p>Avalie anexos, segregações, Fator R, sublimites, substituição tributária e tributos recolhidos fora do documento único. A simplicidade operacional tem valor, mas não elimina a necessidade de conferir a carga total.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Lucro Presumido</h2><p>Considere percentuais de presunção por atividade, IRPJ, adicional, CSLL, PIS, Cofins, ISS ou ICMS e encargos sobre folha. Margens reais muito diferentes da presunção podem alterar a atratividade.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Lucro Real</h2><p>A análise depende do lucro tributável, adições, exclusões, compensações e créditos permitidos. Empresas com margem baixa ou determinadas estruturas de custos podem encontrar vantagens, mas a conformidade tende a ser mais exigente.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Decisão e sensibilidade</h2><p>Não escolha apenas pelo menor valor de um mês. Simule crescimento, queda de margem, contratação, mudança de atividade e sazonalidade. Inclua custo operacional, risco e capacidade de manter controles compatíveis com o regime.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/comparador-tributario\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>O regime com menor imposto sempre é o melhor?</h3><p>Não. Custos de conformidade, fluxo de caixa, riscos e limitações operacionais também fazem parte da decisão.</p><h3>Uma simulação substitui planejamento tributário?</h3><p>Não. Ela organiza premissas e cenários, mas a decisão requer validação técnica conforme a empresa.</p><h3>Quando revisar o regime?</h3><p>Revise antes do período de opção e sempre que houver mudança relevante em receita, margem, atividade ou estrutura.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 3, 'Fiscal e Tributário', 'blog/covers/simples-lucro-presumido-lucro-real-comparacao.png', 'Ilustração do guia: Simples, Lucro Presumido ou Lucro Real: como comparar regimes', 'published', 0, '2026-07-21 12:00:00', '2026-07-21 12:00:00', 'comparar regimes tributários', '[\"Simples ou Lucro Presumido\", \"Lucro Real ou Presumido\", \"planejamento tributário\", \"comparador tributário\"]', 'Simples, Lucro Presumido ou Lucro Real: como comparar regimes', 'Compare Simples Nacional, Lucro Presumido e Lucro Real usando receita, margem, folha, créditos e custos de conformidade.', NULL, 'blog/social/simples-lucro-presumido-lucro-real-comparacao.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20');
INSERT INTO `blog_posts` (`id`, `author_id`, `title`, `slug`, `excerpt`, `content`, `category_id`, `category`, `cover_image_path`, `cover_image_alt`, `status`, `is_featured`, `published_at`, `content_updated_at`, `primary_keyword`, `related_keywords`, `meta_title`, `meta_description`, `canonical_url`, `social_image_path`, `should_index`, `created_at`, `updated_at`) VALUES
(10, NULL, 'Como calcular férias, terço constitucional, abono e prazos', 'como-calcular-ferias-dias-abono-prazos', 'Entenda período aquisitivo, dias de direito, remuneração, médias, terço constitucional, venda de dias e prazos de concessão.', '<p>Entenda período aquisitivo, dias de direito, remuneração, médias, terço constitucional, venda de dias e prazos de concessão.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> revise os dados de entrada, preserve a memória de cálculo e valide o resultado antes de tomar decisões ou transmitir informações oficiais.</div><h2>Período aquisitivo e concessivo</h2><p>O direito é formado ao longo do período aquisitivo e deve ser concedido dentro do período correspondente. Datas de admissão, afastamentos e faltas relevantes precisam ser consideradas antes de calcular valores.</p><p>Na prática, vale criar um checklist padronizado para que a análise não dependa apenas da memória de quem executa a rotina. Campos obrigatórios, fonte de cada dado e data de referência devem ficar visíveis para revisão.</p><h2>Dias de direito</h2><p>A quantidade de dias pode ser afetada por ocorrências previstas em lei. Não reduza férias apenas com base em faltas sem conferir a natureza e a faixa aplicável.</p><p>Quando houver mais de um cenário possível, não esconda as premissas. Mostre o que muda entre eles e quais dados precisam ser confirmados. Isso transforma o cálculo em uma decisão auditável, e não apenas em um número final.</p><h2>Remuneração e médias</h2><p>Parta da remuneração devida na época da concessão e avalie médias de horas extras, adicionais e outras parcelas variáveis quando integrarem a base. Documente o período e o critério usado nas médias.</p><p>Automação ajuda a reduzir digitação e repetir fórmulas, mas não substitui o enquadramento técnico. Use alertas para destacar inconsistências e mantenha os dados originais disponíveis para conferência.</p><h2>Terço e abono pecuniário</h2><p>O terço constitucional incide sobre a remuneração de férias conforme a regra aplicável. O abono converte parte dos dias em valor, mas depende de requisitos e prazo de solicitação. Diferencie abono pecuniário de adiantamento salarial.</p><p>Também é recomendável registrar quem realizou a análise, quando ela foi feita e qual versão das regras foi considerada. Essa trilha reduz retrabalho em revisões futuras.</p><h2>Planejamento e pagamento</h2><p>Além do cálculo, verifique comunicação, início do descanso, feriados, parcelamento permitido e prazo de pagamento. Planejar férias evita concentração de ausências e reduz risco de concessão fora do prazo.</p><p>Antes de concluir, confronte o resultado com documentos de suporte e com a regra vigente na data de referência. Em caso de divergência, investigue a origem em vez de ajustar o valor manualmente sem justificativa.</p><h2>Passo a passo recomendado</h2><ol><li>Reúna documentos e dados do período correto.</li><li>Normalize formatos sem apagar o valor original.</li><li>Informe premissas e datas de referência.</li><li>Execute o cálculo ou validação.</li><li>Revise alertas, bases e memória detalhada.</li><li>Salve a evidência necessária e só então use o resultado.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada a este guia para organizar os dados, visualizar a memória do resultado e identificar pontos que precisam de conferência.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-ferias\">Abrir a ferramenta</a></div></div><h2>Perguntas frequentes</h2><h3>Férias são sempre de 30 dias?</h3><p>O direito pode variar conforme ocorrências e regras aplicáveis ao período.</p><h3>O empregado pode vender todas as férias?</h3><p>Não. O abono pecuniário é limitado e depende de solicitação no prazo adequado.</p><h3>Horas extras entram nas férias?</h3><p>Quando habituais e conforme as regras aplicáveis, podem compor médias da remuneração.</p><h2>Conclusão</h2><p>Um bom resultado depende tanto da fórmula quanto da qualidade das informações utilizadas. Padronize a coleta, documente premissas, revise alertas e mantenha a memória de cálculo. Assim, a ferramenta acelera a rotina sem retirar do profissional a decisão técnica.</p>', 4, 'Trabalhista', 'blog/covers/como-calcular-ferias-dias-abono-prazos.png', 'Ilustração do guia: Como calcular férias, terço constitucional, abono e prazos', 'published', 0, '2026-07-22 12:00:00', '2026-07-22 12:00:00', 'como calcular férias', '[\"calculadora de férias\", \"terço constitucional\", \"abono pecuniário\", \"prazo pagamento férias\"]', 'Como calcular férias, terço constitucional, abono e prazos', 'Calcule férias com período aquisitivo, dias de direito, médias, terço constitucional, abono pecuniário e prazos principais.', NULL, 'blog/social/como-calcular-ferias-dias-abono-prazos.png', 1, '2026-07-23 11:45:13', '2026-07-23 11:51:20'),
(11, NULL, 'Custo de funcionário CLT: como calcular o custo total', 'custo-funcionario-clt-como-calcular-custo-total', 'Veja como montar o custo real de um funcionário CLT, separando salário, benefícios, encargos, férias, 13º e outras provisões sem cair em percentuais genéricos.', '<p>O salário registrado na carteira é apenas uma parte do custo de uma contratação CLT. Para saber quanto um funcionário realmente representa no orçamento, a empresa precisa separar o que é remuneração do mês, benefício, encargo sobre a folha, provisão de direitos futuros e gasto operacional ligado à vaga. Misturar tudo em um percentual único costuma produzir uma resposta rápida, mas pouco confiável.</p><p>Esse cálculo é especialmente útil antes de contratar, ao formar preço de serviços, projetar crescimento da equipe ou comparar cenários. O ponto central não é descobrir um “multiplicador mágico” do salário, e sim construir uma memória que mostre de onde veio cada parcela.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar custo de funcionário clt com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>O que entra no custo de um funcionário CLT</h2><p>Comece pelo salário bruto e acrescente somente parcelas que realmente existam no cenário. Benefícios como vale-refeição, assistência médica e auxílio-alimentação dependem da política da empresa ou de norma coletiva. FGTS e contribuições patronais dependem do enquadramento. Férias, adicional de um terço e 13º são direitos periódicos que, para fins gerenciais, podem ser provisionados mês a mês.</p><p>Também podem existir custos que não aparecem na folha: exame ocupacional, uniforme, equipamentos, software, treinamento, recrutamento e estrutura física. Para decisões de contratação, vale separar esses itens dos encargos trabalhistas, pois alguns são mensais e outros acontecem apenas na entrada ou em momentos específicos.</p><h2>Como calcular as provisões mensais</h2><p>Para planejamento, o 13º pode ser representado por uma fração mensal do valor esperado ao longo do ano. Férias também podem ser provisionadas mensalmente, incluindo o terço constitucional, e os encargos incidentes precisam seguir as bases aplicáveis. O objetivo da provisão gerencial é evitar a falsa impressão de que um mês sem pagamento de férias ou 13º é mais barato do que realmente é.</p><p>A ferramenta deve servir como memória de cenário: informe salário, benefícios e parâmetros aplicáveis e observe quanto cada bloco acrescenta ao custo. Se houver dúvida sobre incidência, não esconda a incerteza dentro de um percentual aproximado.</p><h2>Exemplo prático de custo mensal</h2><p>Imagine uma contratação com salário de R$ 4.000, benefício de alimentação de R$ 600 e plano de saúde empresarial de R$ 350. Só esses três itens já somam R$ 4.950 antes de considerar FGTS, possíveis contribuições patronais, provisão de 13º, férias e terço. Isso mostra por que comparar apenas salário com orçamento disponível costuma subestimar a contratação.</p><p>O exemplo não fixa um percentual total porque a composição muda conforme regime tributário, atividade, benefícios e outras regras. O procedimento correto é montar o cenário com as parcelas reais da empresa e só então obter o total.</p><h2>Custo mensal, anual e por hora</h2><p>O custo mensal ajuda a enxergar desembolso e provisões. O anual é melhor para orçamento porque absorve pagamentos que não se repetem todos os meses. Já o custo por hora pode apoiar formação de preço, desde que a empresa diferencie horas contratuais de horas efetivamente produtivas quando isso for relevante.</p><p>Se o funcionário custa R$ 80 mil por ano, dividir simplesmente por 12 responde uma pergunta; dividir pelo número de horas produtivas responde outra. Não misture os dois indicadores.</p><h2>Erros que mais distorcem a conta</h2><p>Os erros mais comuns são usar um percentual padrão para qualquer empresa, tratar descontos do empregado como custo patronal, esquecer benefícios, ignorar provisões e comparar um custo CLT completo com uma contratação PJ usando apenas a nota fiscal mensal.</p><p>Outro erro é usar o resultado como valor oficial de folha. A calculadora é uma ferramenta de análise e conferência; a apuração efetiva deve respeitar as informações da folha, o enquadramento da empresa, normas coletivas e sistemas oficiais.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/custo-funcionario-clt\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/blog/como-calcular-rescisao-trabalhista\">como calcular rescisão trabalhista</a> e <a href=\"/ferramentas/encargos-trabalhistas\">calculadora de encargos trabalhistas</a>.</p><h2>Perguntas frequentes</h2><h3>O salário líquido representa o custo da empresa?</h3><p>Não. O líquido é o que sobra ao empregado após descontos. O custo da empresa inclui salário bruto e outras parcelas que podem existir, como benefícios, encargos e provisões.</p><h3>Existe um percentual padrão para transformar salário em custo CLT?</h3><p>Não existe um percentual universal confiável. A composição varia por empresa, regime, atividade, benefícios e regras aplicáveis.</p><h3>Vale calcular o custo anual?</h3><p>Sim. O anual ajuda a enxergar férias, 13º, benefícios e despesas que não aparecem de forma uniforme em todos os meses.</p><h2>Conclusão</h2><p>Custo de funcionário CLT é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"O salário líquido representa o custo da empresa?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. O líquido é o que sobra ao empregado após descontos. O custo da empresa inclui salário bruto e outras parcelas que podem existir, como benefícios, encargos e provisões.\"}},{\"@type\":\"Question\",\"name\":\"Existe um percentual padrão para transformar salário em custo CLT?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não existe um percentual universal confiável. A composição varia por empresa, regime, atividade, benefícios e regras aplicáveis.\"}},{\"@type\":\"Question\",\"name\":\"Vale calcular o custo anual?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim. O anual ajuda a enxergar férias, 13º, benefícios e despesas que não aparecem de forma uniforme em todos os meses.\"}}]}</script>', 4, 'Trabalhista', 'blog/covers/custo-funcionario-clt-como-calcular-custo-total.png', 'Ilustração do guia: Custo de funcionário CLT: como calcular o custo total', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:29', 'custo de funcionário CLT', '[\"custo funcionário empresa\", \"custo empregado CLT\", \"encargos funcionário CLT\", \"custo mensal funcionário\"]', 'Custo de funcionário CLT: cálculo completo', 'Entenda o custo real de um funcionário CLT com salário, benefícios, FGTS, provisões de férias e 13º, encargos e exemplo prático.', NULL, 'blog/covers/custo-funcionario-clt-como-calcular-custo-total.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:29'),
(12, NULL, 'Fator R: como calcular e entender os Anexos III e V', 'fator-r-como-calcular-anexo-iii-v', 'Aprenda a calcular o Fator R, organizar folha e receita dos 12 meses, interpretar o limite de 28% e entender quando o resultado pode influenciar os Anexos III e V.', '<p>O Fator R é relevante para determinadas atividades de serviços do Simples Nacional porque relaciona a folha de salários com a receita bruta acumulada. Para as atividades sujeitas à regra, o resultado pode influenciar a tributação entre os Anexos III e V. A conta aritmética é simples; o trabalho importante está em usar a janela correta e saber quais valores pertencem a cada lado da razão.</p><p>Na prática, um Fator R calculado com receita de 12 meses e folha de outro período pode parecer plausível e ainda assim estar errado. Por isso, o melhor uso de uma calculadora é mostrar a memória do cálculo e a distância em relação ao limite aplicável, não apenas exibir um percentual final.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar fator r com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Fórmula do Fator R e o limite de 28%</h2><p>A lógica é dividir a folha considerada para o Fator R pela receita bruta acumulada correspondente e converter o resultado em percentual. Para as atividades alcançadas pelo mecanismo, 28% é o ponto de referência atualmente utilizado para a comparação entre Anexo III e Anexo V. Antes de concluir qualquer enquadramento, confirme se a atividade realmente está sujeita ao Fator R.</p><p>Exemplo didático: se a folha considerada no período for R$ 168.000 e a receita bruta acumulada for R$ 600.000, a razão será 0,28, ou 28%. Se a folha fosse R$ 150.000 com a mesma receita, o percentual seria 25%. O exemplo serve para entender a matemática; a composição da folha e o enquadramento devem seguir a regra vigente.</p><h2>RBT12 e folha precisam conversar</h2><p>A Receita Bruta Total acumulada e a folha usada no numerador precisam respeitar a janela prevista para a competência analisada. Não some 12 meses de receita e apenas os últimos seis meses de folha. Também tenha cuidado com empresas em início de atividade, meses sem movimento e alterações de cadastro.</p><p>Monte uma tabela mensal antes de calcular. Ela facilita encontrar competência duplicada, mês ausente ou valor lançado na coluna errada.</p><h2>O que deve ser conferido na folha</h2><p>O conceito de folha para Fator R não deve ser substituído por um simples “salário dos funcionários”. O cálculo pode envolver remunerações e outros componentes definidos pelas regras do Simples. Use os dados efetivos da empresa e preserve a origem dos valores para permitir conferência posterior.</p><p>Pró-labore merece atenção porque decisões artificiais tomadas apenas para cruzar o limite podem gerar outros efeitos previdenciários, tributários e societários. Planejamento precisa continuar coerente com a realidade econômica.</p><h2>Quanto falta para chegar a 28%</h2><p>Um uso interessante do simulador é responder “qual folha corresponderia a 28% desta receita?”. Com RBT12 de R$ 800.000, por exemplo, 28% representa R$ 224.000. Se a folha considerada estiver em R$ 200.000, a diferença matemática é R$ 24.000. Isso não significa que a empresa deva criar remuneração artificialmente; apenas mostra a distância do cenário atual para o limite.</p><p>A análise fica mais útil quando se projeta também a receita dos próximos meses, porque a saída de um mês antigo e a entrada de um mês novo alteram os acumulados.</p><h2>Quando o resultado não basta para escolher o anexo</h2><p>Fator R não é uma autorização para escolher livremente entre Anexos III e V. Primeiro é necessário confirmar a atividade exercida, seu tratamento no Simples e demais condições aplicáveis. Se a atividade não estiver sujeita ao mecanismo, o percentual calculado não muda o anexo por si só.</p><p>Use a ferramenta para simular e explicar o cálculo; use a apuração oficial e a legislação vigente para fechar a competência.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/simulador-fator-r\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/blog/simples-nacional-como-calcular-das-fator-r\">guia de Simples Nacional, DAS e Fator R</a> e <a href=\"/ferramentas/simulador-pro-labore-ideal\">simulador de pró-labore</a>.</p><h2>Perguntas frequentes</h2><h3>Fator R acima de 28% sempre leva ao Anexo III?</h3><p>Não sozinho. O primeiro passo é confirmar se a atividade está sujeita ao Fator R e se as demais regras de enquadramento são atendidas.</p><h3>Posso usar receita e folha de períodos diferentes?</h3><p>Não. A comparação precisa respeitar a janela prevista para a competência analisada.</p><h3>A calculadora substitui o PGDAS-D?</h3><p>Não. Ela ajuda a simular e conferir os números, enquanto a apuração e emissão do DAS devem seguir os sistemas oficiais.</p><h2>Conclusão</h2><p>Fator R é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Fator R acima de 28% sempre leva ao Anexo III?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não sozinho. O primeiro passo é confirmar se a atividade está sujeita ao Fator R e se as demais regras de enquadramento são atendidas.\"}},{\"@type\":\"Question\",\"name\":\"Posso usar receita e folha de períodos diferentes?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. A comparação precisa respeitar a janela prevista para a competência analisada.\"}},{\"@type\":\"Question\",\"name\":\"A calculadora substitui o PGDAS-D?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Ela ajuda a simular e conferir os números, enquanto a apuração e emissão do DAS devem seguir os sistemas oficiais.\"}}]}</script>', 3, 'Fiscal e Tributário', 'blog/covers/fator-r-como-calcular-anexo-iii-v.png', 'Ilustração do guia: Fator R: como calcular e entender os Anexos III e V', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:29', 'Fator R', '[\"Fator R Simples Nacional\", \"Anexo III ou V\", \"RBT12\", \"folha de salários Fator R\"]', 'Fator R: cálculo, 28% e Anexos III e V', 'Veja como calcular o Fator R no Simples Nacional, quais valores entram na folha e RBT12, como interpretar 28% e evitar erros de período.', NULL, 'blog/covers/fator-r-como-calcular-anexo-iii-v.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:29'),
(13, NULL, 'DAS em atraso: como calcular multa, juros e valor atualizado', 'das-em-atraso-como-calcular-multa-juros', 'Entenda como estimar um DAS vencido, separar principal, multa de mora e juros, escolher a data de pagamento e conferir o valor na emissão oficial.', '<p>Quando o DAS do Simples Nacional vence sem pagamento, o valor original deixa de ser a melhor referência para quitar o débito. O atraso pode gerar multa de mora e juros, e o total muda conforme a data escolhida para pagamento. A utilidade de uma calculadora é estimar o desembolso e explicar os acréscimos antes de emitir a guia oficial.</p><p>Para débitos federais sujeitos à regra geral de mora, a multa é calculada a 0,33% por dia de atraso, limitada a 20%, e os juros seguem a Selic do período, com tratamento próprio para o mês do pagamento. Como taxas e situações do débito podem variar, o documento válido continua sendo a guia atualizada emitida pelos canais oficiais.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar das em atraso com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Separe principal, multa e juros</h2><p>Comece pelo valor principal do DAS, a data original de vencimento e a data em que pretende pagar. Não altere o principal para “embutir” os acréscimos. Uma boa memória mostra três linhas independentes: valor original, multa e juros. Isso permite comparar a simulação com a guia emitida e descobrir rapidamente onde existe diferença.</p><p>Se a empresa retificou a apuração, parcelou o débito ou ele já passou para outra etapa de cobrança, o fluxo pode ser diferente. Nesses casos, não force a regra geral da calculadora.</p><h2>Como funciona a multa de mora</h2><p>Na regra geral federal, a multa cresce 0,33% por dia de atraso até atingir o limite de 20%. Um atraso de 10 dias representa, matematicamente, 3,30% de multa; com 30 dias, 9,90%. O teto impede que a multa continue aumentando indefinidamente depois de alcançar 20%.</p><p>Conte os dias de acordo com a regra aplicável ao débito e confira a data efetiva de pagamento. Um dia de diferença pode mudar a multa enquanto o teto ainda não foi alcançado.</p><h2>Como entram os juros</h2><p>Os juros não devem ser estimados com uma taxa mensal fixa inventada. A atualização utiliza a Selic acumulada do período aplicável e o tratamento do mês de pagamento previsto na regra. Por isso, a calculadora precisa receber ou consultar a taxa correspondente ao intervalo, em vez de congelar um número que rapidamente ficaria desatualizado.</p><p>Se você está apenas planejando caixa, uma estimativa ajuda. Se vai pagar, gere novamente o documento oficial na data do pagamento.</p><h2>Exemplo de leitura do resultado</h2><p>Suponha um DAS original de R$ 2.000 vencido e uma simulação que apresente R$ 132 de multa e R$ 38 de juros. O valor projetado seria R$ 2.170. O número mais importante não é só o total: é conseguir identificar por que os R$ 170 foram acrescentados e qual data foi usada.</p><p>Se a guia oficial apresentar valor diferente, compare primeiro vencimento, data de pagamento, principal após eventual retificação e taxa do período.</p><h2>Quando não usar uma simulação simples</h2><p>Parcelamentos, débitos inscritos, retificações, compensações e situações especiais podem exigir outra forma de atualização. A calculadora não deve fingir que todos os débitos seguem exatamente o mesmo fluxo.</p><p>Use o resultado como conferência e planejamento financeiro. Para pagamento, emissão e regularização, siga o sistema oficial correspondente ao débito.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/das-em-atraso\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/blog/simples-nacional-como-calcular-das-fator-r\">guia do Simples Nacional e DAS</a> e <a href=\"/ferramentas/fluxo-de-caixa\">ferramenta de fluxo de caixa</a>.</p><h2>Perguntas frequentes</h2><h3>A multa do DAS cresce indefinidamente?</h3><p>Não. Na regra geral federal de mora, a multa diária possui limite de 20%.</p><h3>Posso pagar a guia original vencida?</h3><p>O mais seguro é emitir a guia atualizada nos canais oficiais para a data em que o pagamento será realizado.</p><h3>Por que o valor da calculadora pode diferir da guia?</h3><p>Diferenças podem decorrer da data usada, Selic do período, retificação, parcelamento, situação do débito ou outra particularidade da apuração.</p><h2>Conclusão</h2><p>DAS em atraso é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"A multa do DAS cresce indefinidamente?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Na regra geral federal de mora, a multa diária possui limite de 20%.\"}},{\"@type\":\"Question\",\"name\":\"Posso pagar a guia original vencida?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"O mais seguro é emitir a guia atualizada nos canais oficiais para a data em que o pagamento será realizado.\"}},{\"@type\":\"Question\",\"name\":\"Por que o valor da calculadora pode diferir da guia?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Diferenças podem decorrer da data usada, Selic do período, retificação, parcelamento, situação do débito ou outra particularidade da apuração.\"}}]}</script>', 3, 'Fiscal e Tributário', 'blog/covers/das-em-atraso-como-calcular-multa-juros.png', 'Ilustração do guia: DAS em atraso: como calcular multa, juros e valor atualizado', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:29', 'DAS em atraso', '[\"DAS atrasado\", \"multa DAS atraso\", \"juros DAS Simples Nacional\", \"atualizar DAS\"]', 'DAS em atraso: multa, juros e cálculo', 'Veja como estimar DAS em atraso com multa de mora, juros pela Selic e data de pagamento, além de conferir o valor na guia oficial.', NULL, 'blog/covers/das-em-atraso-como-calcular-multa-juros.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:29'),
(14, NULL, 'Encargos trabalhistas: como calcular o custo da folha', 'encargos-trabalhistas-como-calcular-folha', 'Aprenda a separar remuneração, FGTS, encargos patronais e provisões para entender o custo da folha sem aplicar um percentual genérico a todas as empresas.', '<p>“Quanto a empresa paga de encargos sobre um funcionário?” parece uma pergunta de percentual, mas a resposta correta começa pela base de cálculo. Nem toda verba da folha recebe o mesmo tratamento e nem toda empresa possui a mesma composição patronal. Por isso, aplicar um fator fixo ao salário pode ser útil como chute inicial, mas é fraco para orçamento ou conferência.</p><p>Uma análise melhor separa remuneração, depósitos e contribuições da competência, provisões de direitos futuros e benefícios. O resultado mostra não apenas quanto custa, mas por que custa.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar encargos trabalhistas com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Encargo não é a mesma coisa que provisão</h2><p>FGTS e contribuições patronais, quando aplicáveis, são componentes associados à folha e às bases da competência. Férias, terço e 13º podem ser transformados em provisões mensais para fins de gestão, mas não devem ser apresentados como se fossem exatamente o mesmo tipo de obrigação.</p><p>Essa separação é importante para fluxo de caixa: uma provisão gerencial não significa necessariamente desembolso naquele mês.</p><h2>Comece pelas rubricas e pelas bases</h2><p>Liste salário, horas extras, adicionais, comissões e outras verbas da folha. Depois identifique quais componentes entram na base de cada encargo. O erro clássico é multiplicar toda a remuneração por vários percentuais sem verificar incidência.</p><p>Uma memória bem montada permite clicar em uma parcela e enxergar: base de R$ X, alíquota Y, valor resultante Z. Isso facilita auditoria e explicação ao cliente.</p><h2>Exemplo gerencial sem percentual mágico</h2><p>Considere salário de R$ 3.500, comissão de R$ 500 e benefício de R$ 600. A remuneração bruta do exemplo é R$ 4.000, enquanto o benefício deve ser tratado conforme sua natureza. A partir daí entram FGTS e eventuais componentes patronais segundo as regras da empresa, além das provisões escolhidas para planejamento.</p><p>Perceba que dizer simplesmente “o funcionário custa 70% a mais” esconderia quais valores estão sendo considerados e dificultaria comparar dois cenários.</p><h2>Por que regime tributário e atividade importam</h2><p>O tratamento previdenciário patronal pode variar com regime e atividade. RAT, terceiros e outras contribuições também dependem do enquadramento. Essa é a razão prática para a calculadora permitir parâmetros e não prometer uma alíquota universal.</p><p>Sempre que houver mudança de atividade, regime ou estrutura da folha, revise os parâmetros antes de reutilizar um cenário antigo.</p><h2>Como usar o resultado na gestão</h2><p>Separe o total em custo recorrente mensal, provisões e despesas eventuais. Use o recorrente para acompanhar margem e o anual para planejar caixa. Se a empresa vende horas de serviço, converta o custo total para uma base de horas coerente com sua capacidade produtiva.</p><p>Para obrigações oficiais, reconcilie a simulação com folha, eSocial e demais sistemas aplicáveis.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/encargos-trabalhistas\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/custo-funcionario-clt\">calculadora de custo de funcionário CLT</a> e <a href=\"/blog/como-calcular-ferias-dias-abono-prazos\">guia de cálculo de férias</a>.</p><h2>Perguntas frequentes</h2><h3>Encargos trabalhistas são um percentual fixo?</h3><p>Não. Bases, regime, atividade e rubricas podem alterar a composição.</p><h3>Férias e 13º podem entrar no custo mensal?</h3><p>Para planejamento gerencial, podem ser provisionados mensalmente, desde que fique claro que são provisões de direitos com momentos próprios de pagamento.</p><h3>FGTS é desconto do trabalhador?</h3><p>Não. Nas hipóteses aplicáveis, o depósito é obrigação do empregador e não deve ser confundido com desconto salarial.</p><h2>Conclusão</h2><p>Encargos trabalhistas é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Encargos trabalhistas são um percentual fixo?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Bases, regime, atividade e rubricas podem alterar a composição.\"}},{\"@type\":\"Question\",\"name\":\"Férias e 13º podem entrar no custo mensal?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Para planejamento gerencial, podem ser provisionados mensalmente, desde que fique claro que são provisões de direitos com momentos próprios de pagamento.\"}},{\"@type\":\"Question\",\"name\":\"FGTS é desconto do trabalhador?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Nas hipóteses aplicáveis, o depósito é obrigação do empregador e não deve ser confundido com desconto salarial.\"}}]}</script>', 4, 'Trabalhista', 'blog/covers/encargos-trabalhistas-como-calcular-folha.png', 'Ilustração do guia: Encargos trabalhistas: como calcular o custo da folha', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:29', 'encargos trabalhistas', '[\"cálculo encargos trabalhistas\", \"custo folha pagamento\", \"FGTS empregador\", \"provisão férias 13º\"]', 'Encargos trabalhistas: cálculo da folha', 'Veja como calcular encargos trabalhistas, FGTS e provisões, entender bases de incidência e montar uma memória de custo da folha.', NULL, 'blog/covers/encargos-trabalhistas-como-calcular-folha.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:29'),
(15, NULL, 'CLT, PJ ou autônomo: como comparar custos e valor líquido', 'clt-pj-autonomo-comparar-custos', 'Compare CLT, PJ e autônomo em uma mesma base anual, considerando custo do contratante, líquido estimado, benefícios, tributos, períodos sem faturamento e riscos do vínculo.', '<p>Comparar CLT, PJ e autônomo olhando apenas “quanto cai na conta” cria uma comparação injusta. No emprego existem benefícios, férias, 13º e encargos. Na prestação por pessoa jurídica existem tributos, contabilidade, períodos sem faturamento e custos próprios. No trabalho autônomo há regras previdenciárias e tributárias específicas. A primeira tarefa é colocar os três cenários na mesma unidade de tempo.</p><p>O comparador é útil para negociação e planejamento, mas não decide a natureza jurídica da relação. Se os fatos configuram vínculo de emprego, uma conta mais barata não transforma a realidade em prestação independente.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar clt, pj ou autônomo com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Compare o mesmo período</h2><p>Prefira uma visão anual. Um salário CLT mensal não deve ser comparado diretamente com 12 notas fiscais PJ sem considerar férias e outros períodos. Do lado do contratante, some tudo que efetivamente compõe o custo anual. Do lado do profissional, estime o líquido anual após tributos e custos próprios.</p><p>Depois, se quiser, transforme os totais anuais em média mensal. Isso evita favorecer artificialmente um modelo.</p><h2>O que considerar no cenário CLT</h2><p>Inclua salário, benefícios, encargos e provisões aplicáveis. Para o valor percebido pelo trabalhador, considere também benefícios econômicos que não aparecem no líquido bancário. Vale-refeição de R$ 800 por mês, por exemplo, representa R$ 9.600 ao ano se pago por 12 meses.</p><p>Não trate férias e 13º como “bônus gratuito”: eles fazem parte da estrutura econômica do emprego e precisam estar presentes na comparação.</p><h2>O que considerar no cenário PJ</h2><p>Na PJ, comece pelo faturamento esperado e desconte tributos do regime escolhido, honorários contábeis, taxas, softwares, seguros e outros custos necessários. Reserve ainda períodos sem faturamento se o profissional quiser reproduzir férias ou intervalos entre contratos.</p><p>Exemplo: uma nota de R$ 10.000 não significa R$ 10.000 líquidos. Se o negócio tem R$ 1.000 de tributos e R$ 600 de custos operacionais naquele cenário, a base disponível já cai para R$ 8.400 antes de outras decisões.</p><h2>O que considerar como autônomo</h2><p>O trabalho autônomo pode envolver retenções, contribuição previdenciária e imposto conforme o caso. Não copie o cenário PJ trocando apenas o nome, pois bases e obrigações são diferentes.</p><p>Use os parâmetros efetivos do serviço e do pagador. O comparador deve deixar claro o que é estimativa e o que depende de apuração.</p><h2>Custo menor não resolve o risco jurídico</h2><p>Subordinação, pessoalidade, habitualidade, onerosidade e demais elementos da relação precisam ser analisados pelos fatos. A ferramenta compara números; ela não serve para “validar” pejotização ou mascarar vínculo.</p><p>A melhor decisão combina viabilidade econômica com enquadramento jurídico compatível com a forma real de trabalho.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/comparador-clt-pj-autonomo\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/custo-funcionario-clt\">custo de funcionário CLT</a> e <a href=\"/ferramentas/simulador-pro-labore-ideal\">simulador de pró-labore</a>.</p><h2>Perguntas frequentes</h2><h3>PJ sempre dá mais líquido?</h3><p>Não. Depende do valor negociado, tributos, custos próprios, benefícios perdidos e tempo sem faturamento.</p><h3>Qual é a melhor base para comparar?</h3><p>Uma base anual costuma ser mais justa porque incorpora parcelas e períodos que não aparecem igualmente em todos os meses.</p><h3>A calculadora pode dizer qual contratação é legal?</h3><p>Não. Ela compara cenários financeiros; a natureza jurídica depende dos fatos e das regras aplicáveis.</p><h2>Conclusão</h2><p>CLT, PJ ou autônomo é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"PJ sempre dá mais líquido?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Depende do valor negociado, tributos, custos próprios, benefícios perdidos e tempo sem faturamento.\"}},{\"@type\":\"Question\",\"name\":\"Qual é a melhor base para comparar?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Uma base anual costuma ser mais justa porque incorpora parcelas e períodos que não aparecem igualmente em todos os meses.\"}},{\"@type\":\"Question\",\"name\":\"A calculadora pode dizer qual contratação é legal?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Ela compara cenários financeiros; a natureza jurídica depende dos fatos e das regras aplicáveis.\"}}]}</script>', 4, 'Trabalhista', 'blog/covers/clt-pj-autonomo-comparar-custos.png', 'Ilustração do guia: CLT, PJ ou autônomo: como comparar custos e valor líquido', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:29', 'CLT, PJ ou autônomo', '[\"CLT x PJ\", \"CLT ou PJ\", \"autônomo ou PJ\", \"custo contratação CLT PJ\"]', 'CLT x PJ x autônomo: compare custos', 'Veja como comparar CLT, PJ e autônomo com a mesma base econômica, benefícios, tributos, custo anual e valor líquido estimado.', NULL, 'blog/covers/clt-pj-autonomo-comparar-custos.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:29'),
(16, NULL, 'INSS patronal: como calcular CPP, RAT e terceiros', 'inss-patronal-como-calcular-cpp-rat-terceiros', 'Entenda como decompor o custo previdenciário patronal entre CPP, RAT e contribuições a terceiros, conferindo base de folha e enquadramento antes de aplicar alíquotas.', '<p>“INSS patronal” é um nome prático para um conjunto de componentes que não deve ser reduzido automaticamente a uma única alíquota. Dependendo do enquadramento da empresa, podem existir contribuição previdenciária patronal, componente associado aos riscos ambientais do trabalho e contribuições destinadas a terceiros. Regime tributário, atividade e outras regras podem mudar o resultado.</p><p>A calculadora é mais útil quando apresenta cada componente isoladamente. Assim, se o total divergir da apuração oficial, você consegue investigar base, alíquota e enquadramento em vez de tentar ajustar o valor final no escuro.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar inss patronal com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Primeiro confirme a base de remunerações</h2><p>Antes de olhar alíquotas, confira quais remunerações entram na base do cenário. Salário, adicionais, comissões e outras rubricas podem ter tratamentos próprios. Uma base errada multiplicada pela alíquota correta continua produzindo um cálculo errado.</p><p>Use a mesma competência da folha e preserve uma lista das rubricas que formaram a base.</p><h2>CPP não deve ser presumida para todos os casos</h2><p>A regra previdenciária patronal depende do enquadramento. Empresas em situações específicas podem ter tratamento distinto da regra geral. Por isso, o simulador deve permitir parametrização e deixar claro quando um percentual foi informado pelo usuário.</p><p>Se a empresa mudou regime ou atividade, não reutilize automaticamente a configuração do mês anterior sem conferir.</p><h2>RAT, atividade preponderante e ajuste</h2><p>O componente de risco está relacionado ao enquadramento da atividade e pode sofrer ajustes previstos na legislação. Copiar o RAT de outra empresa do mesmo setor é uma prática fraca: confirme os dados da própria organização e a informação vigente.</p><p>Na memória, mostre a base, a alíquota aplicada e o valor separadamente.</p><h2>Terceiros e FPAS</h2><p>As contribuições destinadas a outras entidades e fundos podem depender do FPAS e do enquadramento. Elas ajudam a explicar por que duas empresas com folhas de mesmo valor podem ter custo patronal diferente.</p><p>Em vez de “INSS = X%”, prefira um quadro: CPP, RAT/ajuste, terceiros e total. Isso também melhora a conferência com os sistemas oficiais.</p><h2>Exemplo de decomposição</h2><p>Suponha uma base de folha de R$ 50.000 e parâmetros hipotéticos informados pelo usuário de 20% para CPP, 2% para o componente de risco e 5,8% para terceiros. A memória mostraria R$ 10.000, R$ 1.000 e R$ 2.900, totalizando R$ 13.900. O exemplo é matemático e não afirma que esses percentuais sejam os corretos para uma empresa específica.</p><p>A utilidade do exemplo é mostrar a decomposição. Na operação real, use os parâmetros do enquadramento efetivo e confronte com eSocial/DCTFWeb ou sistema aplicável.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/inss-patronal\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/encargos-trabalhistas\">calculadora de encargos trabalhistas</a> e <a href=\"/ferramentas/custo-funcionario-clt\">custo de funcionário CLT</a>.</p><h2>Perguntas frequentes</h2><h3>INSS patronal é sempre 20%?</h3><p>Não como resposta universal. O enquadramento da empresa e os componentes da contribuição precisam ser analisados.</p><h3>RAT é igual em todas as empresas?</h3><p>Não. Ele depende do enquadramento da atividade e de ajustes aplicáveis.</p><h3>Por que separar terceiros?</h3><p>Porque possuem lógica e enquadramento próprios e ajudam a explicar o custo patronal total da folha.</p><h2>Conclusão</h2><p>INSS patronal é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"INSS patronal é sempre 20%?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não como resposta universal. O enquadramento da empresa e os componentes da contribuição precisam ser analisados.\"}},{\"@type\":\"Question\",\"name\":\"RAT é igual em todas as empresas?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Ele depende do enquadramento da atividade e de ajustes aplicáveis.\"}},{\"@type\":\"Question\",\"name\":\"Por que separar terceiros?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Porque possuem lógica e enquadramento próprios e ajudam a explicar o custo patronal total da folha.\"}}]}</script>', 4, 'Trabalhista', 'blog/covers/inss-patronal-como-calcular-cpp-rat-terceiros.png', 'Ilustração do guia: INSS patronal: como calcular CPP, RAT e terceiros', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:29', 'INSS patronal', '[\"cálculo INSS patronal\", \"CPP empresa\", \"RAT FAP\", \"contribuição terceiros FPAS\"]', 'INSS patronal: CPP, RAT e terceiros', 'Veja como analisar INSS patronal separando CPP, RAT e terceiros, validar a base da folha e evitar o erro de usar uma alíquota única.', NULL, 'blog/covers/inss-patronal-como-calcular-cpp-rat-terceiros.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:29');
INSERT INTO `blog_posts` (`id`, `author_id`, `title`, `slug`, `excerpt`, `content`, `category_id`, `category`, `cover_image_path`, `cover_image_alt`, `status`, `is_featured`, `published_at`, `content_updated_at`, `primary_keyword`, `related_keywords`, `meta_title`, `meta_description`, `canonical_url`, `social_image_path`, `should_index`, `created_at`, `updated_at`) VALUES
(17, NULL, 'Capital de giro: como calcular NCG e necessidade financeira', 'capital-de-giro-como-calcular-ncg', 'Aprenda a calcular necessidade de capital de giro com contas a receber, estoques e fornecedores, comparar com recursos de curto prazo e interpretar a pressão sobre o caixa.', '<p>Uma empresa pode ser lucrativa e ainda faltar dinheiro para pagar as contas. Isso acontece quando o ciclo operacional exige recursos antes de o dinheiro das vendas entrar. A necessidade de capital de giro ajuda a transformar esse descasamento em um número: quanto da operação está sendo financiado pela própria empresa e quanto já é sustentado por fornecedores e outras obrigações operacionais.</p><p>O cálculo fica realmente útil quando todas as contas pertencem à mesma data-base e são classificadas pela sua função operacional. Misturar saldos de dias diferentes ou colocar empréstimos junto de fornecedores pode distorcer a leitura.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar capital de giro com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Entenda a lógica da NCG</h2><p>Em uma leitura gerencial simplificada, ativos operacionais de curto prazo — como clientes a receber e estoques — consomem capital. Passivos operacionais — como fornecedores e certas obrigações do ciclo — financiam parte dessa necessidade. A diferença entre os dois mostra a NCG.</p><p>Não classifique pela aparência do nome da conta. Pergunte se aquele saldo nasce diretamente da operação e do ciclo de compra, produção, venda e recebimento.</p><h2>Exemplo numérico</h2><p>Imagine R$ 120.000 em contas a receber e R$ 80.000 em estoques. Os ativos operacionais somam R$ 200.000. Se fornecedores e obrigações operacionais totalizam R$ 130.000, a necessidade de capital de giro do exemplo é R$ 70.000.</p><p>Esse R$ 70.000 não é automaticamente um empréstimo a contratar. É a parcela do ciclo que precisa ser financiada por capital próprio, dívida financeira ou outra fonte.</p><h2>NCG não é a mesma coisa que saldo bancário</h2><p>Caixa mostra disponibilidade em um momento. NCG mostra quanto o ciclo operacional exige. Uma empresa pode ter R$ 200.000 no banco e NCG crescente, ou caixa apertado com NCG baixa por causa de uma dívida financeira próxima do vencimento.</p><p>Por isso, combine o indicador com fluxo de caixa e dívida de curto prazo.</p><h2>Use sempre a mesma data-base</h2><p>Se contas a receber são de 30 de junho, estoque é de 31 de maio e fornecedores são de 15 de julho, a fotografia deixa de representar um único momento. Para acompanhar tendência, calcule a NCG em várias datas separadas e compare a evolução.</p><p>Uma série mensal mostra se o crescimento da empresa está consumindo cada vez mais caixa.</p><h2>Como reduzir a necessidade sem simplesmente tomar crédito</h2><p>Ações comuns incluem reduzir prazo de recebimento, aumentar giro de estoque, negociar prazo com fornecedores e eliminar itens parados. Cada ação tem efeito comercial e operacional; portanto, não deve ser tomada só para melhorar o indicador.</p><p>O melhor uso da calculadora é testar cenários: “o que acontece se o prazo de recebimento cair?” ou “quanto capital é liberado se o estoque reduzir 15%?”.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/capital-de-giro\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/fluxo-de-caixa\">projeção de fluxo de caixa</a> e <a href=\"/ferramentas/ponto-de-equilibrio\">calculadora de ponto de equilíbrio</a>.</p><h2>Perguntas frequentes</h2><h3>NCG positiva é ruim?</h3><p>Não necessariamente. Muitos negócios precisam financiar o ciclo. O importante é saber o tamanho, tendência e fonte de financiamento.</p><h3>Capital de giro é igual a dinheiro no banco?</h3><p>Não. Caixa é disponibilidade; capital de giro e NCG analisam a estrutura financeira de curto prazo e o ciclo operacional.</p><h3>Posso usar saldos de datas diferentes?</h3><p>Não é recomendável. O indicador deve representar uma fotografia consistente da mesma data-base.</p><h2>Conclusão</h2><p>Capital de giro é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"NCG positiva é ruim?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não necessariamente. Muitos negócios precisam financiar o ciclo. O importante é saber o tamanho, tendência e fonte de financiamento.\"}},{\"@type\":\"Question\",\"name\":\"Capital de giro é igual a dinheiro no banco?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Caixa é disponibilidade; capital de giro e NCG analisam a estrutura financeira de curto prazo e o ciclo operacional.\"}},{\"@type\":\"Question\",\"name\":\"Posso usar saldos de datas diferentes?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não é recomendável. O indicador deve representar uma fotografia consistente da mesma data-base.\"}}]}</script>', 1, 'Gestão Contábil', 'blog/covers/capital-de-giro-como-calcular-ncg.png', 'Ilustração do guia: Capital de giro: como calcular NCG e necessidade financeira', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:29', 'capital de giro', '[\"necessidade de capital de giro\", \"NCG\", \"capital circulante líquido\", \"cálculo capital de giro\"]', 'Capital de giro: calcule NCG e necessidade', 'Veja como calcular capital de giro e NCG, classificar contas operacionais, usar a mesma data-base e interpretar a necessidade de financiamento.', NULL, 'blog/covers/capital-de-giro-como-calcular-ncg.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:29'),
(18, NULL, 'Fluxo de caixa: como calcular entradas, saídas e saldo', 'fluxo-de-caixa-como-calcular-saldo', 'Monte um fluxo de caixa por data de recebimento e pagamento, projete o saldo final e identifique períodos de falta ou sobra de recursos sem misturar caixa e competência.', '<p>Fluxo de caixa não mede apenas se a empresa vendeu bem; ele mostra quando o dinheiro entra e quando sai. Uma venda de R$ 30.000 parcelada para os próximos três meses pode aumentar receita hoje e ainda não resolver o pagamento da folha desta semana. Por isso, projeção de caixa deve seguir datas de recebimento e pagamento.</p><p>A ferramenta fica mais útil quando separa o realizado do previsto. Assim você consegue ver o saldo de hoje, o que já aconteceu e o que depende de clientes pagarem ou despesas vencerem.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar fluxo de caixa com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Comece por um saldo inicial conciliado</h2><p>Escolha uma data e registre o dinheiro realmente disponível no início do período. Defina se aplicações de liquidez imediata entram no saldo e se contas bloqueadas ficam de fora. O importante é manter o mesmo critério nos períodos seguintes.</p><p>Se o saldo inicial não bate com bancos e caixa, toda projeção nasce contaminada.</p><h2>Entrada é recebimento, não faturamento</h2><p>No fluxo de caixa, uma nota emitida não vira entrada até ocorrer o recebimento. Se uma venda de R$ 12.000 será paga em três parcelas de R$ 4.000, projete cada parcela na data esperada. Faça o mesmo com recebimentos recorrentes, impostos recuperáveis ou outros ingressos.</p><p>Isso evita a sensação falsa de liquidez criada por contas a receber elevadas.</p><h2>Saída é pagamento</h2><p>Registre folha, fornecedores, impostos, aluguel, financiamentos, investimentos e demais pagamentos na data prevista. Se uma compra será paga em 30 e 60 dias, divida a saída conforme o vencimento em vez de lançar tudo na data da compra.</p><p>Separar despesas operacionais, financeiras e investimentos ajuda a entender por que o caixa está mudando.</p><h2>Exemplo de projeção</h2><p>Suponha saldo inicial de R$ 20.000, recebimentos de R$ 35.000 e pagamentos de R$ 42.000 no mês. O saldo final projetado é R$ 13.000. Se R$ 10.000 dos recebimentos dependem de um cliente historicamente atrasado, crie também um cenário conservador; nele o saldo poderia cair para R$ 3.000.</p><p>O cenário alternativo é mais útil para decisão do que uma única projeção otimista.</p><h2>Como identificar o dia do aperto</h2><p>Uma visão apenas mensal pode esconder que o saldo fica negativo no dia 15 e se recupera no dia 28. Para empresas com caixa apertado, projete por semana ou por dia os grandes movimentos.</p><p>Quando aparecer um vale negativo, a empresa pode antecipar negociação com fornecedor, cobrança de cliente ou reserva de capital, em vez de descobrir o problema no vencimento.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/fluxo-de-caixa\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/capital-de-giro\">calculadora de capital de giro</a> e <a href=\"/ferramentas/ponto-de-equilibrio\">ponto de equilíbrio</a>.</p><h2>Perguntas frequentes</h2><h3>Fluxo de caixa é igual a DRE?</h3><p>Não. A DRE trabalha com resultado econômico e competência; o fluxo acompanha entradas e saídas de dinheiro.</p><h3>Devo lançar venda quando emito a nota?</h3><p>No fluxo de caixa, o ideal é lançar na data em que o dinheiro deve entrar.</p><h3>Vale fazer mais de um cenário?</h3><p>Sim. Cenários base, conservador e otimista ajudam a enxergar risco de atraso em recebimentos ou aumento de pagamentos.</p><h2>Conclusão</h2><p>Fluxo de caixa é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Fluxo de caixa é igual a DRE?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. A DRE trabalha com resultado econômico e competência; o fluxo acompanha entradas e saídas de dinheiro.\"}},{\"@type\":\"Question\",\"name\":\"Devo lançar venda quando emito a nota?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"No fluxo de caixa, o ideal é lançar na data em que o dinheiro deve entrar.\"}},{\"@type\":\"Question\",\"name\":\"Vale fazer mais de um cenário?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim. Cenários base, conservador e otimista ajudam a enxergar risco de atraso em recebimentos ou aumento de pagamentos.\"}}]}</script>', 1, 'Gestão Contábil', 'blog/covers/fluxo-de-caixa-como-calcular-saldo.png', 'Ilustração do guia: Fluxo de caixa: como calcular entradas, saídas e saldo', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:46', 'fluxo de caixa', '[\"cálculo fluxo de caixa\", \"saldo de caixa\", \"entradas e saídas\", \"projeção fluxo de caixa\"]', 'Fluxo de caixa: entradas, saídas e saldo', 'Aprenda a montar fluxo de caixa com saldo inicial, entradas, saídas e projeções, usando datas reais de recebimento e pagamento.', NULL, 'blog/covers/fluxo-de-caixa-como-calcular-saldo.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:46'),
(19, NULL, 'Ponto de equilíbrio: como calcular quanto a empresa precisa vender', 'ponto-de-equilibrio-como-calcular', 'Calcule o faturamento necessário para cobrir custos fixos usando margem de contribuição e veja como preço, custos variáveis e mix de vendas alteram o ponto de equilíbrio.', '<p>O ponto de equilíbrio responde a uma pergunta essencial: quanto a empresa precisa vender para que a margem gerada pelas vendas cubra os custos fixos do período? A resposta é diferente de “quanto precisa faturar para sobrar dinheiro”, porque depende da margem de contribuição e da estrutura de custos.</p><p>Se preço de venda ou custo variável mudam, o ponto de equilíbrio também muda. Por isso, a calculadora é especialmente útil para testar cenários antes de aumentar preço, contratar estrutura ou lançar um produto.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar ponto de equilíbrio com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Primeiro calcule a margem de contribuição</h2><p>A margem de contribuição é o que sobra da venda depois dos custos e despesas variáveis diretamente ligados a ela. Se um produto é vendido por R$ 100 e possui R$ 55 de custos variáveis, a margem de contribuição unitária é R$ 45, ou 45% do preço.</p><p>Não coloque aluguel ou salário administrativo como variável só porque são pagos todo mês. A classificação deve refletir se o valor muda diretamente com as vendas.</p><h2>Fórmula do ponto de equilíbrio em faturamento</h2><p>Em uma abordagem gerencial simples, divida os custos fixos pela margem de contribuição percentual. Se custos fixos são R$ 30.000 e a margem é 40%, o ponto de equilíbrio de faturamento é R$ 75.000. Abaixo disso, a margem não cobre a estrutura fixa; acima, começa a existir resultado operacional antes de outros efeitos não considerados.</p><p>O cálculo pressupõe que a margem usada represente adequadamente o mix de vendas.</p><h2>Ponto de equilíbrio em unidades</h2><p>Para um único produto, também é possível dividir custos fixos pela margem unitária. Com R$ 30.000 de custos fixos e R$ 45 de margem por unidade, seriam necessárias aproximadamente 667 unidades para cobrir a estrutura no exemplo.</p><p>Se a empresa vende muitos produtos, uma margem média ponderada costuma ser mais representativa do que escolher um item isolado.</p><h2>Como preço e desconto alteram o resultado</h2><p>Um desconto pequeno no preço pode aumentar bastante o ponto de equilíbrio quando a margem já é apertada. No exemplo de preço R$ 100 e variável R$ 55, reduzir o preço para R$ 90 derruba a margem unitária para R$ 35. A empresa precisa vender muito mais unidades para cobrir os mesmos custos fixos.</p><p>Antes de conceder desconto recorrente, simule o volume adicional necessário para compensar a perda de margem.</p><h2>Não confunda equilíbrio com caixa</h2><p>Mesmo acima do ponto de equilíbrio econômico, a empresa pode ter falta de caixa por causa de prazos de recebimento, parcelas de dívida, investimentos ou formação de estoque. Combine o indicador com fluxo de caixa e capital de giro.</p><p>O ponto de equilíbrio é uma régua de viabilidade operacional, não um retrato completo de liquidez.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/ponto-de-equilibrio\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/fluxo-de-caixa\">fluxo de caixa</a> e <a href=\"/ferramentas/capital-de-giro\">capital de giro</a>.</p><h2>Perguntas frequentes</h2><h3>Ponto de equilíbrio é o mesmo que faturamento mínimo?</h3><p>É uma referência de faturamento necessário para cobrir a estrutura considerada no cálculo, baseada na margem de contribuição.</p><h3>Desconto aumenta o ponto de equilíbrio?</h3><p>Em geral, sim, se reduzir a margem de contribuição e os demais fatores permanecerem iguais.</p><h3>Posso usar margem média?</h3><p>Sim, especialmente em empresas com vários produtos, desde que a média seja ponderada de forma coerente com o mix de vendas.</p><h2>Conclusão</h2><p>Ponto de equilíbrio é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Ponto de equilíbrio é o mesmo que faturamento mínimo?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"É uma referência de faturamento necessário para cobrir a estrutura considerada no cálculo, baseada na margem de contribuição.\"}},{\"@type\":\"Question\",\"name\":\"Desconto aumenta o ponto de equilíbrio?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Em geral, sim, se reduzir a margem de contribuição e os demais fatores permanecerem iguais.\"}},{\"@type\":\"Question\",\"name\":\"Posso usar margem média?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim, especialmente em empresas com vários produtos, desde que a média seja ponderada de forma coerente com o mix de vendas.\"}}]}</script>', 1, 'Gestão Contábil', 'blog/covers/ponto-de-equilibrio-como-calcular.png', 'Ilustração do guia: Ponto de equilíbrio: como calcular em valor e quantidade', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:46', 'ponto de equilíbrio', '[\"cálculo ponto de equilíbrio\", \"break even\", \"margem de contribuição\", \"quantidade mínima vendas\"]', 'Ponto de equilíbrio: fórmula e exemplo', 'Aprenda a calcular ponto de equilíbrio com custos fixos e margem de contribuição, veja exemplo numérico e entenda como interpretar o resultado.', NULL, 'blog/covers/ponto-de-equilibrio-como-calcular.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:46'),
(20, NULL, 'Pró-labore ideal: como definir e simular o valor dos sócios', 'pro-labore-ideal-como-calcular-inss-irrf', 'Entenda como definir pró-labore de forma coerente com a atividade do sócio, capacidade da empresa, encargos aplicáveis e separação entre remuneração e lucros.', '<p>Pró-labore é a remuneração pelo trabalho do sócio na empresa. Ele não deve ser confundido com distribuição de lucros, retirada informal de caixa ou simples transferência bancária para despesas pessoais. Definir um valor coerente exige olhar a função exercida, a realidade financeira do negócio e os efeitos previdenciários e tributários aplicáveis.</p><p>Não existe um número “ideal” universal. O simulador serve para comparar cenários e mostrar o impacto da escolha, não para inventar uma justificativa automática para o menor valor possível.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar pró-labore ideal com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Comece pela função realmente exercida</h2><p>Descreva o trabalho do sócio: dedicação, responsabilidade, frequência e papel operacional. Essa descrição ajuda a discutir uma remuneração coerente e documentável. Um sócio que trabalha diariamente na operação está em situação diferente de um investidor que não presta serviços.</p><p>A definição deve ser compatível com os fatos e com as regras aplicáveis ao caso.</p><h2>Separe pró-labore de distribuição de lucros</h2><p>Pró-labore remunera trabalho. Lucro distribuído decorre do resultado empresarial apurado e documentado. Misturar os dois enfraquece a organização contábil e torna difícil explicar a origem das retiradas.</p><p>Uma boa rotina registra cada transferência com sua natureza e mantém decisões societárias e escrituração coerentes.</p><h2>Simule o impacto no caixa</h2><p>Imagine uma empresa com dois sócios operacionais. Um cenário de R$ 5.000 de pró-labore para cada um gera R$ 10.000 de remuneração bruta mensal antes dos encargos e tributos relacionados. Um cenário de R$ 7.000 para cada um sobe a base para R$ 14.000. O simulador ajuda a comparar o custo e o líquido estimado em cada alternativa.</p><p>Não escolha um valor que a empresa não consegue sustentar apenas para atingir outro indicador.</p><h2>Relação com Fator R</h2><p>Em empresas sujeitas ao Fator R, elementos da folha podem influenciar o percentual. Isso torna o pró-labore relevante em simulações, mas não transforma a remuneração em uma variável puramente fiscal. A decisão precisa ter substância e documentação.</p><p>Use o simulador de Fator R em conjunto para visualizar o efeito matemático sem perder de vista as demais consequências.</p><h2>Revise quando a empresa ou a função mudar</h2><p>Crescimento do negócio, mudança de responsabilidade, entrada de novos sócios ou alteração relevante de caixa são bons momentos para revisar o valor. Evite deixar a mesma quantia por anos apenas por hábito.</p><p>Documente a data da revisão e os critérios usados. Isso melhora governança e consistência.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/simulador-pro-labore-ideal\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/distribuicao-de-lucros\">simulador de distribuição de lucros</a> e <a href=\"/ferramentas/simulador-fator-r\">simulador de Fator R</a>.</p><h2>Perguntas frequentes</h2><h3>Existe um pró-labore mínimo universal?</h3><p>Não há um único valor que resolva todos os casos. É preciso considerar atividade do sócio, regras aplicáveis e realidade da empresa.</p><h3>Pró-labore é igual a lucro distribuído?</h3><p>Não. Um remunera trabalho; o outro decorre do resultado empresarial e possui condições próprias.</p><h3>Posso definir pró-labore só para melhorar o Fator R?</h3><p>A simulação pode mostrar o efeito, mas a remuneração deve continuar coerente com a atividade efetivamente exercida e demais regras aplicáveis.</p><h2>Conclusão</h2><p>Pró-labore ideal é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Existe um pró-labore mínimo universal?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não há um único valor que resolva todos os casos. É preciso considerar atividade do sócio, regras aplicáveis e realidade da empresa.\"}},{\"@type\":\"Question\",\"name\":\"Pró-labore é igual a lucro distribuído?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Um remunera trabalho; o outro decorre do resultado empresarial e possui condições próprias.\"}},{\"@type\":\"Question\",\"name\":\"Posso definir pró-labore só para melhorar o Fator R?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A simulação pode mostrar o efeito, mas a remuneração deve continuar coerente com a atividade efetivamente exercida e demais regras aplicáveis.\"}}]}</script>', 3, 'Fiscal e Tributário', 'blog/covers/pro-labore-ideal-como-calcular-inss-irrf.png', 'Ilustração do guia: Pró-labore ideal: como calcular INSS, IRRF e valor líquido', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:46', 'pró-labore ideal', '[\"cálculo pró-labore\", \"INSS pró-labore\", \"IRRF pró-labore\", \"valor pró-labore sócio\"]', 'Pró-labore ideal: como definir e simular', 'Veja como definir pró-labore dos sócios, separar remuneração de distribuição de lucros e simular impacto no caixa e nos encargos.', NULL, 'blog/covers/pro-labore-ideal-como-calcular-inss-irrf.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:46'),
(21, NULL, 'Comissão de vendedores: como calcular metas, percentuais e valor a pagar', 'comissao-vendedores-como-calcular', 'Veja como estruturar comissão de vendas por percentual, faixa ou meta, calcular estornos e conferir a base antes de fechar o pagamento da equipe.', '<p>Comissão parece simples quando a regra é “5% das vendas”, mas dúvidas aparecem rapidamente: 5% sobre preço cheio ou valor com desconto? Venda faturada ou recebida? Cancelamento reduz a comissão? Há faixas por meta? Sem uma política clara, a mesma planilha pode gerar resultados diferentes para vendedor e empresa.</p><p>A calculadora deve transformar a política comercial em memória de cálculo, mostrando base, percentual, ajustes e valor final.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar comissão de vendedores com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Defina a base antes do percentual</h2><p>Escolha o evento que gera comissão: pedido aprovado, faturamento, recebimento ou outro marco previsto na política. Depois defina quais valores entram na base e como tratar frete, impostos destacados, descontos, devoluções e cancelamentos.</p><p>Escrever isso antes do fechamento reduz discussões e evita alterações retroativas.</p><h2>Exemplo de comissão simples</h2><p>Se a base comissionável do mês é R$ 80.000 e o percentual definido é 3%, a comissão bruta do exemplo é R$ 2.400. Se R$ 5.000 em vendas forem cancelados antes do evento que gera direito à comissão, a base pode precisar ser ajustada conforme a regra adotada.</p><p>A memória deve mostrar as vendas incluídas e os ajustes, não apenas R$ 2.400 como número final.</p><h2>Comissão por faixas ou metas</h2><p>Uma política pode pagar 2% até determinado volume e 3% acima de uma meta. É importante definir se o percentual maior incide sobre todas as vendas ou somente sobre a parcela excedente. As duas regras produzem resultados diferentes.</p><p>Exemplo: se a meta é R$ 100.000 e o vendedor fecha R$ 120.000, pagar 3% sobre os R$ 120.000 é diferente de pagar 2% sobre os primeiros R$ 100.000 e 3% sobre os R$ 20.000 excedentes.</p><h2>Devoluções, inadimplência e estornos</h2><p>Defina previamente como cada evento afeta a comissão e em qual competência o ajuste aparece. Evite descontar valores sem memória que relacione o estorno à venda original.</p><p>Para equipes grandes, um identificador de pedido ou nota em cada linha facilita auditoria.</p><h2>Use comissão para incentivar o comportamento certo</h2><p>Uma regra baseada apenas em faturamento pode estimular desconto excessivo ou venda com baixa margem. Dependendo do negócio, metas de margem, recebimento ou mix podem ser mais saudáveis.</p><p>Antes de mudar a política, simule meses históricos para ver quanto cada modelo teria pago e quais comportamentos ele recompensa.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/comissao-vendedores\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/gerador-holerite\">gerador de holerite</a> e <a href=\"/ferramentas/ponto-de-equilibrio\">ponto de equilíbrio</a>.</p><h2>Perguntas frequentes</h2><h3>Comissão deve ser calculada sobre venda ou recebimento?</h3><p>Depende da política definida e das regras aplicáveis. O importante é estabelecer o evento gerador claramente e aplicar o mesmo critério.</p><h3>Posso ter percentuais diferentes por faixa?</h3><p>Sim, desde que a regra deixe claro como as faixas funcionam e sobre qual parcela cada percentual incide.</p><h3>Como tratar cancelamento?</h3><p>Defina a regra previamente e preserve a referência à venda original para que qualquer estorno possa ser conferido.</p><h2>Conclusão</h2><p>Comissão de vendedores é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Comissão deve ser calculada sobre venda ou recebimento?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Depende da política definida e das regras aplicáveis. O importante é estabelecer o evento gerador claramente e aplicar o mesmo critério.\"}},{\"@type\":\"Question\",\"name\":\"Posso ter percentuais diferentes por faixa?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim, desde que a regra deixe claro como as faixas funcionam e sobre qual parcela cada percentual incide.\"}},{\"@type\":\"Question\",\"name\":\"Como tratar cancelamento?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Defina a regra previamente e preserve a referência à venda original para que qualquer estorno possa ser conferido.\"}}]}</script>', 1, 'Gestão Contábil', 'blog/covers/comissao-vendedores-como-calcular.png', 'Ilustração do guia: Comissão de vendedores: como calcular comissão e metas', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:46', 'comissão de vendedores', '[\"cálculo comissão vendas\", \"comissão vendedor\", \"meta de vendas bônus\", \"base comissionável\"]', 'Comissão de vendedores: cálculo e exemplos', 'Aprenda a calcular comissão de vendedores por percentual, faixa e meta, definir a base e evitar erros com cancelamentos, devoluções e descontos.', NULL, 'blog/covers/comissao-vendedores-como-calcular.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:46'),
(22, NULL, 'Como preencher um holerite: proventos, descontos e conferência', 'holerite-como-calcular-proventos-descontos', 'Aprenda a organizar dados de um holerite, separar proventos e descontos, conferir bases e evitar erros antes de gerar o demonstrativo de pagamento.', '<p>O holerite é um demonstrativo: ele precisa explicar como o valor líquido do empregado foi formado. Um documento visualmente bonito não corrige uma folha calculada com rubricas, bases ou competência erradas. Por isso, antes de gerar o PDF, organize os dados da remuneração e confira a origem de cada desconto.</p><p>O gerador é útil para montar e apresentar o demonstrativo, mas não substitui a apuração da folha nem o envio de obrigações trabalhistas.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar como preencher um holerite com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Identifique empregado, empresa e competência</h2><p>Comece pelos dados básicos e pelo período a que o pagamento se refere. Erro de competência é especialmente problemático porque pode fazer um demonstrativo correto ser associado ao mês errado.</p><p>Use nomes, documentos e função exatamente como devem aparecer no demonstrativo e mantenha os dados pessoais protegidos.</p><h2>Separe proventos por rubrica</h2><p>Salário, horas extras, adicional noturno, comissão, gratificação e outras verbas devem aparecer em linhas independentes quando existirem. Isso permite ao empregado entender por que o bruto aumentou ou diminuiu.</p><p>Evite lançar uma rubrica genérica “outros” para valores relevantes sem descrição.</p><h2>Descontos precisam ser rastreáveis</h2><p>INSS, IRRF, faltas, adiantamentos, benefícios e outros descontos devem seguir a folha efetivamente apurada. O gerador não deve “inventar” descontos para fazer o líquido bater com um valor desejado.</p><p>Se a conta não fecha, investigue a origem na folha antes de editar manualmente o demonstrativo.</p><h2>Exemplo de conferência</h2><p>Imagine proventos de R$ 4.500 e descontos totais de R$ 850. O líquido é R$ 3.650. Antes de gerar, confira se a soma das rubricas de provento realmente chega a R$ 4.500 e se os descontos listados totalizam R$ 850. O teste de soma encontra muitos erros de digitação.</p><p>Depois compare bases e valores com o sistema que originou a folha.</p><h2>O que guardar junto do holerite</h2><p>Mantenha a folha ou memória que originou o demonstrativo e o comprovante de pagamento, conforme a rotina documental da empresa. O objetivo é conseguir reproduzir o valor no futuro sem depender apenas do PDF final.</p><p>Ao corrigir um holerite, preserve a versão ou registro de alteração conforme sua política interna.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/gerador-holerite\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/encargos-trabalhistas\">encargos trabalhistas</a> e <a href=\"/blog/como-calcular-ferias-dias-abono-prazos\">cálculo de férias</a>.</p><h2>Perguntas frequentes</h2><h3>Holerite e folha de pagamento são a mesma coisa?</h3><p>Não. O holerite é um demonstrativo individual; a folha é o processo e conjunto de cálculos da remuneração.</p><h3>O gerador calcula automaticamente todos os tributos?</h3><p>Ele deve usar os dados e regras implementadas, mas a conferência com a folha oficial continua necessária.</p><h3>Posso corrigir um líquido alterando um desconto manualmente?</h3><p>Não é uma boa prática. Primeiro descubra qual rubrica ou base está incorreta na apuração.</p><h2>Conclusão</h2><p>Como preencher um holerite é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Holerite e folha de pagamento são a mesma coisa?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. O holerite é um demonstrativo individual; a folha é o processo e conjunto de cálculos da remuneração.\"}},{\"@type\":\"Question\",\"name\":\"O gerador calcula automaticamente todos os tributos?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Ele deve usar os dados e regras implementadas, mas a conferência com a folha oficial continua necessária.\"}},{\"@type\":\"Question\",\"name\":\"Posso corrigir um líquido alterando um desconto manualmente?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não é uma boa prática. Primeiro descubra qual rubrica ou base está incorreta na apuração.\"}}]}</script>', 4, 'Trabalhista', 'blog/covers/holerite-como-calcular-proventos-descontos.png', 'Ilustração do guia: Holerite: como calcular proventos, descontos e salário líquido', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:46', 'holerite', '[\"como fazer holerite\", \"cálculo salário líquido\", \"proventos descontos folha\", \"contracheque\"]', 'Como preencher holerite: guia de conferência', 'Veja como preencher holerite com salário, adicionais, descontos e bases, conferir o líquido e organizar um demonstrativo de pagamento claro.', NULL, 'blog/covers/holerite-como-calcular-proventos-descontos.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:46'),
(23, NULL, 'Admissão de funcionário: custos e checklist antes da contratação', 'admissao-como-calcular-custo-contratacao', 'Planeje a admissão separando custo recorrente, despesas de entrada, documentos e etapas cadastrais para saber o impacto real da nova contratação.', '<p>A decisão de contratar não deveria terminar na pergunta “qual será o salário?”. A admissão cria custos recorrentes, despesas de entrada e uma sequência de documentos e registros que precisam estar prontos no momento correto. Um simulador útil separa esses três blocos para que o orçamento não misture mensalidade com gasto pontual.</p><p>O checklist reduz retrabalho porque mostra o que precisa ser confirmado antes do início do empregado, sem substituir os eventos e registros exigidos pelos sistemas oficiais.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar admissão de funcionário com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Separe custo mensal de custo de entrada</h2><p>Salário, benefícios e encargos formam o custo recorrente. Exame ocupacional, recrutamento, uniforme, equipamento e treinamento inicial podem ser despesas de entrada. Misturar tudo em um único percentual dificulta saber quanto a vaga custa no primeiro mês e quanto custa depois.</p><p>Crie no simulador duas linhas de total: investimento inicial e custo mensal estimado.</p><h2>Exemplo de orçamento da admissão</h2><p>Considere salário de R$ 3.800, benefícios mensais de R$ 900 e R$ 2.500 em notebook e equipamentos. Mesmo antes de calcular encargos e provisões, o primeiro mês já tem uma estrutura diferente dos meses seguintes por causa do investimento inicial.</p><p>Se a empresa contratar dez pessoas ao mesmo tempo, essa diferença pode ter impacto relevante no caixa.</p><h2>Checklist de informações do empregado</h2><p>Confirme dados cadastrais, função, salário, jornada, local de trabalho, data de início, benefícios e documentos necessários conforme a rotina aplicável. Evite coletar informação sem finalidade e proteja os dados pessoais recebidos.</p><p>Qualquer divergência encontrada antes do início é mais simples de corrigir do que depois de a folha estar fechada.</p><h2>Planeje acessos e estrutura</h2><p>Admissão também é operacional: e-mail, sistemas, equipamentos, permissões e treinamento precisam estar prontos. Um funcionário contratado e sem acesso pode gerar custo sem produtividade nos primeiros dias.</p><p>Inclua responsáveis e prazos no checklist, não apenas uma lista de documentos.</p><h2>Conferência antes do primeiro fechamento</h2><p>Antes da primeira folha, compare salário, jornada, benefícios e data de admissão com o que foi aprovado. Erros nessa fase tendem a se repetir em competências futuras se forem cadastrados como padrão.</p><p>Use o simulador para orçamento e o sistema oficial de folha/eSocial para os registros e cálculos obrigatórios.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/simulador-admissao\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/custo-funcionario-clt\">custo de funcionário CLT</a> e <a href=\"/ferramentas/gerador-holerite\">gerador de holerite</a>.</p><h2>Perguntas frequentes</h2><h3>Quanto custa admitir um funcionário?</h3><p>Depende do salário, benefícios, encargos aplicáveis e despesas específicas de entrada. Separe custo recorrente e investimento inicial.</p><h3>Checklist de admissão substitui o eSocial?</h3><p>Não. Ele organiza a preparação; os registros oficiais continuam necessários.</p><h3>Equipamento entra no custo mensal?</h3><p>Para análise, normalmente vale separá-lo como custo de entrada ou depreciá-lo conforme a finalidade gerencial, em vez de misturá-lo automaticamente à folha mensal.</p><h2>Conclusão</h2><p>Admissão de funcionário é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Quanto custa admitir um funcionário?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Depende do salário, benefícios, encargos aplicáveis e despesas específicas de entrada. Separe custo recorrente e investimento inicial.\"}},{\"@type\":\"Question\",\"name\":\"Checklist de admissão substitui o eSocial?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. Ele organiza a preparação; os registros oficiais continuam necessários.\"}},{\"@type\":\"Question\",\"name\":\"Equipamento entra no custo mensal?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Para análise, normalmente vale separá-lo como custo de entrada ou depreciá-lo conforme a finalidade gerencial, em vez de misturá-lo automaticamente à folha mensal.\"}}]}</script>', 4, 'Trabalhista', 'blog/covers/admissao-como-calcular-custo-contratacao.png', 'Ilustração do guia: Admissão de funcionário: como calcular o custo da contratação', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:46', 'admissão de funcionário', '[\"custo admissão funcionário\", \"checklist admissional\", \"contratação CLT custos\", \"simulador admissão\"]', 'Admissão de funcionário: custos e checklist', 'Veja custos e checklist de admissão, incluindo salário, benefícios, encargos, exames, documentos e etapas antes de contratar um funcionário.', NULL, 'blog/covers/admissao-como-calcular-custo-contratacao.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:46');
INSERT INTO `blog_posts` (`id`, `author_id`, `title`, `slug`, `excerpt`, `content`, `category_id`, `category`, `cover_image_path`, `cover_image_alt`, `status`, `is_featured`, `published_at`, `content_updated_at`, `primary_keyword`, `related_keywords`, `meta_title`, `meta_description`, `canonical_url`, `social_image_path`, `should_index`, `created_at`, `updated_at`) VALUES
(24, NULL, 'Reajuste salarial: como calcular percentual, retroativo e novo salário', 'reajuste-salarial-como-calcular-retroativo', 'Aprenda a calcular reajuste salarial por percentual, diferença mensal e retroativo, organizando data-base e competências para conferir o novo valor.', '<p>Calcular o novo salário após um reajuste é simples; calcular corretamente todas as diferenças pode não ser. Quando o percentual é definido com efeito retroativo, entram data-base, competências afetadas, verbas calculadas sobre o salário e eventuais pagamentos já realizados.</p><p>A calculadora deve primeiro mostrar a matemática do reajuste e depois organizar as competências retroativas. O percentual e a data de vigência precisam vir da regra aplicável ao empregado, como instrumento coletivo ou decisão da empresa, e não ser presumidos pela ferramenta.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar reajuste salarial com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Como calcular o novo salário</h2><p>A fórmula básica é salário anterior multiplicado por um mais o percentual de reajuste. Com salário de R$ 3.000 e reajuste de 6%, o acréscimo é R$ 180 e o novo salário é R$ 3.180.</p><p>Evite arredondar o percentual no meio do cálculo. Use o percentual oficial informado e aplique o critério de arredondamento adotado na folha.</p><h2>Diferença mensal e retroativo</h2><p>Se o novo salário deveria valer em competência anterior, calcule a diferença de cada mês separadamente. No exemplo, a diferença salarial pura é R$ 180 por mês. Três competências completas representariam R$ 540 de diferença salarial antes de analisar repercussões em outras verbas.</p><p>Não multiplique cegamente por meses quando houve férias, afastamentos, mudança salarial ou jornada diferente no período.</p><h2>Verbas que podem precisar de revisão</h2><p>Horas extras, adicionais, férias, 13º e outras verbas calculadas a partir do salário podem exigir análise quando o reajuste alcança competências já fechadas. A repercussão depende do caso e das regras aplicáveis.</p><p>Uma boa memória identifica quais competências e rubricas foram recalculadas.</p><h2>Data-base, vigência e pagamento</h2><p>São três datas diferentes: a referência da negociação, a data em que o novo salário passa a produzir efeito e a data em que a diferença será efetivamente paga. Confundir essas datas é fonte comum de erro.</p><p>Registre-as no cenário para que outra pessoa consiga reproduzir o cálculo.</p><h2>Não use percentual antigo por hábito</h2><p>Reajustes coletivos mudam conforme categoria, instrumento e período. A ferramenta não deve manter um percentual padrão “do ano passado”. Informe o percentual vigente para o caso e guarde a origem.</p><p>Se houver pisos ou regras adicionais, confira o instrumento aplicável antes de fechar a folha.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/reajuste-salarial\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/gerador-holerite\">gerador de holerite</a> e <a href=\"/ferramentas/encargos-trabalhistas\">encargos trabalhistas</a>.</p><h2>Perguntas frequentes</h2><h3>Como calcular reajuste de 6%?</h3><p>Multiplique o salário anterior por 1,06. Um salário de R$ 3.000 passaria para R$ 3.180 no exemplo.</p><h3>Retroativo é apenas diferença de salário vezes meses?</h3><p>Nem sempre. Outras verbas e mudanças ocorridas no período podem exigir recálculo específico.</p><h3>A calculadora sabe qual percentual da convenção?</h3><p>Não deve presumir isso. Use o percentual e as datas do instrumento aplicável ao empregado e à categoria.</p><h2>Conclusão</h2><p>Reajuste salarial é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Como calcular reajuste de 6%?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Multiplique o salário anterior por 1,06. Um salário de R$ 3.000 passaria para R$ 3.180 no exemplo.\"}},{\"@type\":\"Question\",\"name\":\"Retroativo é apenas diferença de salário vezes meses?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Nem sempre. Outras verbas e mudanças ocorridas no período podem exigir recálculo específico.\"}},{\"@type\":\"Question\",\"name\":\"A calculadora sabe qual percentual da convenção?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não deve presumir isso. Use o percentual e as datas do instrumento aplicável ao empregado e à categoria.\"}}]}</script>', 4, 'Trabalhista', 'blog/covers/reajuste-salarial-como-calcular-retroativo.png', 'Ilustração do guia: Reajuste salarial: como calcular novo salário e retroativo', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:58', 'reajuste salarial', '[\"cálculo reajuste salarial\", \"aumento salarial percentual\", \"retroativo salarial\", \"novo salário\"]', 'Reajuste salarial: cálculo e retroativo', 'Veja como calcular reajuste salarial, novo salário e diferenças retroativas, com exemplo numérico e cuidados com data-base e convenção.', NULL, 'blog/covers/reajuste-salarial-como-calcular-retroativo.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:58'),
(25, NULL, 'Distribuição de lucros: como calcular o valor de cada sócio', 'distribuicao-de-lucros-como-calcular-socios', 'Calcule a divisão de lucros entre sócios a partir do lucro disponível, percentuais de participação, regra de distribuição e saldo que permanecerá na empresa.', '<p>Saldo bancário não é sinônimo de lucro disponível para distribuição. Antes de dividir valores entre os sócios, a empresa precisa partir de resultado apurado e documentado, considerar prejuízos ou reservas quando aplicáveis e decidir quanto pode sair sem comprometer o caixa.</p><p>A calculadora entra depois dessa etapa: ela distribui uma base informada segundo percentuais ou regra definida e mostra quanto cada sócio recebe e quanto permanece na empresa.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar distribuição de lucros com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Comece pelo lucro que pode ser distribuído</h2><p>Não use faturamento ou dinheiro no banco como atalho. A base precisa vir da apuração contábil e das condições aplicáveis à empresa. Se há lucro de R$ 200.000 no período, isso não significa que os R$ 200.000 devam ser transferidos imediatamente.</p><p>Considere compromissos futuros, capital de giro e decisões societárias antes de definir o montante a distribuir.</p><h2>Divisão proporcional</h2><p>Se a empresa decidiu distribuir R$ 120.000 e os sócios possuem participações de 60% e 40%, a divisão proporcional do exemplo é R$ 72.000 e R$ 48.000. A soma dos percentuais precisa totalizar a regra esperada e a memória deve mostrar os valores individualmente.</p><p>Distribuições com regra diferente da participação exigem análise e documentação compatíveis com o contrato e a legislação aplicável.</p><h2>Pró-labore não deve ser escondido dentro do lucro</h2><p>O sócio que trabalha na empresa pode ter pró-labore. Essa remuneração possui natureza distinta da distribuição do resultado. Transferir tudo sob o rótulo de lucro reduz a qualidade da documentação e pode criar risco.</p><p>Mantenha as duas naturezas em registros separados.</p><h2>Quanto deixar na empresa</h2><p>Depois de definir o valor distribuído, calcule o saldo remanescente e confronte-o com fluxo de caixa e necessidade de capital de giro. Uma distribuição tecnicamente possível pode ser financeiramente imprudente se deixar a empresa sem caixa para impostos, folha ou estoque.</p><p>Simule diferentes percentuais de retenção antes da decisão.</p><h2>Documente a decisão</h2><p>Registre período do lucro, base utilizada, sócios beneficiados, valores e data da deliberação ou procedimento societário aplicável. A calculadora pode gerar uma memória, mas não substitui os registros contábeis e societários necessários.</p><p>Se houver dúvida sobre tributação ou condições da distribuição, valide a regra vigente antes do pagamento.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/distribuicao-de-lucros\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/simulador-pro-labore-ideal\">simulador de pró-labore</a> e <a href=\"/ferramentas/capital-de-giro\">capital de giro</a>.</p><h2>Perguntas frequentes</h2><h3>Posso distribuir o saldo da conta bancária?</h3><p>Não é uma base adequada por si só. Distribuição de lucros deve partir de resultado apurado e das condições aplicáveis.</p><h3>A divisão precisa seguir exatamente a participação societária?</h3><p>A divisão proporcional é a regra mais simples de simular, mas outras formas exigem verificar o contrato, a legislação e a documentação aplicável.</p><h3>Pró-labore e lucro podem ser somados em uma única transferência?</h3><p>É melhor manter natureza, cálculo e documentação separados para preservar clareza e rastreabilidade.</p><h2>Conclusão</h2><p>Distribuição de lucros é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Posso distribuir o saldo da conta bancária?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não é uma base adequada por si só. Distribuição de lucros deve partir de resultado apurado e das condições aplicáveis.\"}},{\"@type\":\"Question\",\"name\":\"A divisão precisa seguir exatamente a participação societária?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A divisão proporcional é a regra mais simples de simular, mas outras formas exigem verificar o contrato, a legislação e a documentação aplicável.\"}},{\"@type\":\"Question\",\"name\":\"Pró-labore e lucro podem ser somados em uma única transferência?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"É melhor manter natureza, cálculo e documentação separados para preservar clareza e rastreabilidade.\"}}]}</script>', 3, 'Fiscal e Tributário', 'blog/covers/distribuicao-de-lucros-como-calcular-socios.png', 'Ilustração do guia: Distribuição de lucros: como calcular o valor de cada sócio', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:58', 'distribuição de lucros', '[\"cálculo distribuição lucros\", \"lucro por sócio\", \"participação societária\", \"divisão de lucros empresa\"]', 'Distribuição de lucros: cálculo por sócio', 'Veja como calcular distribuição de lucros por participação, separar pró-labore e lucro, validar a base e preservar capital de giro.', NULL, 'blog/covers/distribuicao-de-lucros-como-calcular-socios.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:58'),
(26, NULL, 'Declaração de rendimentos: como preencher valores e período corretamente', 'declaracao-de-rendimentos-como-preencher', 'Veja como organizar uma declaração de rendimentos com identificação, período, origem e valores, evitando misturar faturamento, renda líquida e documentos comprobatórios.', '<p>Uma declaração de rendimentos é útil quando alguém precisa apresentar, de forma organizada, quais valores recebeu em determinado período. O documento fica fraco quando usa termos vagos como “renda média” sem explicar de onde o número veio, ou quando mistura faturamento bruto de uma atividade com renda efetivamente recebida pela pessoa.</p><p>O gerador ajuda a estruturar o texto, mas quem declara continua responsável pela veracidade dos dados e por apresentar documentos adicionais quando a instituição destinatária exigir.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar declaração de rendimentos com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Defina exatamente o que está sendo declarado</h2><p>Escreva se o valor representa rendimentos recebidos, faturamento da atividade, pró-labore, prestação de serviços ou outra origem. Não use “renda” para grandezas diferentes sem explicação.</p><p>Se houver mais de uma origem, liste cada uma separadamente e depois apresente o total.</p><h2>Escolha um período verificável</h2><p>Prefira datas claras, como janeiro a junho de 2026, ou uma lista mensal. Uma média de seis meses é mais informativa quando o documento também mostra os valores que formaram a média.</p><p>Evite declarar uma média baseada em meses escolhidos apenas porque foram os melhores.</p><h2>Exemplo de organização</h2><p>Suponha rendimentos de R$ 4.800, R$ 5.100 e R$ 5.300 em três meses. O total do período é R$ 15.200 e a média simples é aproximadamente R$ 5.066,67. O documento pode apresentar tanto o total quanto a média e indicar que ela foi calculada sobre três competências.</p><p>Se os valores forem brutos, escreva “brutos”; se líquidos, explique o critério usado.</p><h2>Documentos de apoio</h2><p>Extratos, notas fiscais, recibos, informes, declarações fiscais ou registros contábeis podem ser solicitados pelo destinatário. A declaração não transforma um valor não comprovado em prova absoluta.</p><p>Antes de enviar, veja quais documentos a instituição aceita e evite incluir dados pessoais desnecessários.</p><h2>Assinatura e responsabilidade</h2><p>Identifique o declarante, data e finalidade quando necessário. Assinatura eletrônica ou física pode ser exigida conforme o uso do documento. O gerador organiza o conteúdo; ele não autentica fatos por conta própria.</p><p>Guarde a versão enviada para saber exatamente o que foi declarado.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/declaracao-rendimentos\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/declaracao-trabalho-renda\">declaração de trabalho e renda</a> e <a href=\"/ferramentas/emissor-de-recibos\">emissor de recibos</a>.</p><h2>Perguntas frequentes</h2><h3>Declaração de rendimentos substitui comprovantes?</h3><p>Nem sempre. A instituição pode exigir extratos, notas, informe de rendimentos ou outros documentos.</p><h3>Posso declarar média mensal?</h3><p>Sim, desde que o período e os valores usados para formar a média estejam claros.</p><h3>Faturamento é igual a rendimento pessoal?</h3><p>Não necessariamente. Faturamento da atividade e renda da pessoa são conceitos diferentes e devem ser descritos corretamente.</p><h2>Conclusão</h2><p>Declaração de rendimentos é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Declaração de rendimentos substitui comprovantes?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Nem sempre. A instituição pode exigir extratos, notas, informe de rendimentos ou outros documentos.\"}},{\"@type\":\"Question\",\"name\":\"Posso declarar média mensal?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim, desde que o período e os valores usados para formar a média estejam claros.\"}},{\"@type\":\"Question\",\"name\":\"Faturamento é igual a rendimento pessoal?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não necessariamente. Faturamento da atividade e renda da pessoa são conceitos diferentes e devem ser descritos corretamente.\"}}]}</script>', 3, 'Fiscal e Tributário', 'blog/covers/declaracao-de-rendimentos-como-preencher.png', 'Ilustração do guia: Declaração de rendimentos: como preencher e revisar o documento', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:58', 'declaração de rendimentos', '[\"como fazer declaração rendimentos\", \"comprovante de rendimentos\", \"declaração renda\", \"rendimentos brutos líquidos\"]', 'Declaração de rendimentos: como preencher', 'Aprenda a preencher declaração de rendimentos com período, origem, valores e identificação, além de entender quando anexar comprovantes.', NULL, 'blog/covers/declaracao-de-rendimentos-como-preencher.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:58'),
(27, NULL, 'Declaração de trabalho e renda: como fazer e quais dados incluir', 'declaracao-trabalho-renda-como-fazer', 'Monte uma declaração de trabalho e renda com atividade, período, valor e identificação do declarante, deixando claro o que o documento comprova e quais anexos podem ser exigidos.', '<p>Uma declaração de trabalho e renda é um documento particular usado para registrar que uma pessoa exerce determinada atividade e recebe valores relacionados a ela. Pode ser solicitada em cadastros, locações, análises internas e outras situações, mas a aceitação depende de quem recebe o documento.</p><p>A declaração deve descrever fatos verificáveis. Ela não cria vínculo empregatício, não transforma prestação informal em contrato e não garante que uma instituição aceitará o valor como única prova de renda.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar declaração de trabalho e renda com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Descreva a atividade sem exagerar</h2><p>Informe qual trabalho é realizado, desde quando e em que condição, usando linguagem compatível com os fatos. Evite declarar “empregado”, “autônomo” ou outra qualificação jurídica apenas para atender um formulário se isso não corresponde à situação real.</p><p>Quando houver contrato ou CNPJ relacionado, mencione somente o que puder ser comprovado.</p><h2>Explique o valor da renda</h2><p>Diga se o valor é mensal fixo, média, variável ou referente a um período específico. Se for média, informe a janela utilizada. Isso é mais transparente do que apresentar um número isolado.</p><p>Exemplo: “média de R$ 4.700 nos últimos seis meses” é melhor quando o declarante consegue demonstrar quais meses compõem a média.</p><h2>Identificação e finalidade</h2><p>Inclua nome e dados necessários do declarante e, quando fizer sentido, a finalidade do documento. Não coloque CPF, endereço completo ou outros dados sensíveis se o destinatário não precisar deles.</p><p>A versão final deve conter data e forma de assinatura adequada ao uso.</p><h2>O que pode acompanhar a declaração</h2><p>Extratos bancários, notas fiscais, recibos, contratos e documentos fiscais podem reforçar a comprovação. Cada instituição adota seus próprios requisitos, portanto verifique antes de enviar um pacote excessivo de documentos.</p><p>O gerador pode deixar um campo para anexos ou observações sem afirmar que eles são obrigatórios em todos os casos.</p><h2>Cuidado com frases que prometem demais</h2><p>Evite expressões como “comprova definitivamente” ou “possui validade para qualquer finalidade”. Uma declaração registra o que o declarante afirma e sua força depende do contexto, dos documentos de apoio e das regras do destinatário.</p><p>O conteúdo deve ser verdadeiro, específico e proporcional à finalidade.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/declaracao-trabalho-renda\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/declaracao-rendimentos\">declaração de rendimentos</a> e <a href=\"/ferramentas/gerador-de-contratos\">gerador de contratos</a>.</p><h2>Perguntas frequentes</h2><h3>A declaração cria vínculo de emprego?</h3><p>Não por si só. A natureza da relação depende dos fatos e das regras aplicáveis.</p><h3>Ela comprova renda sozinha?</h3><p>A instituição pode exigir documentos adicionais, como extratos, notas ou declarações fiscais.</p><h3>Precisa ter assinatura?</h3><p>Para uso como declaração particular, a assinatura costuma ser importante, observados os requisitos de quem receberá o documento.</p><h2>Conclusão</h2><p>Declaração de trabalho e renda é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"A declaração cria vínculo de emprego?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não por si só. A natureza da relação depende dos fatos e das regras aplicáveis.\"}},{\"@type\":\"Question\",\"name\":\"Ela comprova renda sozinha?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A instituição pode exigir documentos adicionais, como extratos, notas ou declarações fiscais.\"}},{\"@type\":\"Question\",\"name\":\"Precisa ter assinatura?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Para uso como declaração particular, a assinatura costuma ser importante, observados os requisitos de quem receberá o documento.\"}}]}</script>', 1, 'Gestão Contábil', 'blog/covers/declaracao-trabalho-renda-como-fazer.png', 'Ilustração do guia: Declaração de trabalho e renda: como fazer corretamente', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:58', 'declaração de trabalho e renda', '[\"como fazer declaração de trabalho\", \"declaração de renda autônomo\", \"declaração atividade profissional\", \"comprovante trabalho renda\"]', 'Declaração de trabalho e renda: modelo e guia', 'Veja como fazer declaração de trabalho e renda com atividade, período, valor, identificação e assinatura, sem prometer validade além dos fatos declarados.', NULL, 'blog/covers/declaracao-trabalho-renda-como-fazer.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:58'),
(28, NULL, 'Contrato de prestação de serviços: cláusulas essenciais e cuidados', 'como-fazer-contrato-gerador-contratos', 'Entenda como organizar escopo, preço, prazo, entregas, responsabilidades, rescisão e proteção de dados em um contrato de prestação de serviços.', '<p>Um contrato de prestação de serviços é mais útil quando reduz ambiguidades antes do trabalho começar. O maior risco não é faltar linguagem jurídica sofisticada; é deixar sem resposta perguntas práticas como “o que será entregue?”, “quando?”, “quanto custa?”, “o que acontece se o cliente pedir algo fora do escopo?” e “como o contrato termina?”.</p><p>O gerador pode estruturar uma minuta inicial, mas contratos com risco elevado, propriedade intelectual relevante, dados sensíveis, valores altos ou relações complexas merecem revisão jurídica adequada ao caso.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar contrato de prestação de serviços com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Escopo deve ser verificável</h2><p>Troque frases como “prestar suporte completo” por entregas observáveis: quantidade de reuniões, horas incluídas, relatórios, canais, prazo de resposta ou funcionalidades. Quanto mais subjetivo o escopo, maior a chance de conflito.</p><p>Inclua também o que não está incluído quando houver expectativa comum de serviços extras.</p><h2>Preço, forma e condição de pagamento</h2><p>Defina valor, vencimento, forma de cobrança e se existem etapas ou parcelas. Se houver reembolso de despesas, diga quais precisam de aprovação. Se o preço pode mudar com escopo adicional, descreva como a alteração será aprovada.</p><p>Evite deixar reajustes ou multas em campos genéricos sem critério.</p><h2>Prazo, aceite e mudança de escopo</h2><p>O contrato deve explicar quando o serviço começa, duração, marcos de entrega e como o cliente registra aceite ou solicita correção. Para projetos, um processo simples de mudança de escopo evita que pedidos extras sejam absorvidos silenciosamente.</p><p>Uma cláusula pode exigir orçamento complementar antes de iniciar trabalho não previsto.</p><h2>Confidencialidade, dados e propriedade intelectual</h2><p>Se uma parte acessa informações confidenciais ou dados pessoais, descreva responsabilidades compatíveis com o serviço. Em trabalhos criativos ou de software, deixe claro quem mantém direitos sobre materiais preexistentes e o que será cedido ou licenciado após pagamento.</p><p>Não copie cláusulas extensas que não tenham relação com o projeto apenas para parecer mais completo.</p><h2>Rescisão e encerramento</h2><p>Defina como qualquer parte pode encerrar o contrato, prazo de aviso quando houver e como serão tratados valores de trabalhos já executados. Também vale prever devolução de materiais, revogação de acessos e entrega de arquivos.</p><p>Uma boa cláusula de saída reduz o custo de um relacionamento que não está funcionando.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/gerador-de-contratos\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/emissor-de-recibos\">emissor de recibos</a> e <a href=\"/ferramentas/declaracao-trabalho-renda\">declaração de trabalho e renda</a>.</p><h2>Perguntas frequentes</h2><h3>Um modelo de contrato serve para qualquer serviço?</h3><p>Não. A estrutura pode ser reaproveitada, mas escopo, riscos e cláusulas devem refletir o serviço real.</p><h3>Preciso detalhar tudo no corpo do contrato?</h3><p>Pode usar anexos ou propostas para detalhar escopo e entregas, desde que fique claro como esses documentos se integram ao contrato.</p><h3>O gerador substitui advogado?</h3><p>Não em casos que exigem análise jurídica. Ele organiza uma minuta e ajuda a não esquecer informações essenciais.</p><h2>Conclusão</h2><p>Contrato de prestação de serviços é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Um modelo de contrato serve para qualquer serviço?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. A estrutura pode ser reaproveitada, mas escopo, riscos e cláusulas devem refletir o serviço real.\"}},{\"@type\":\"Question\",\"name\":\"Preciso detalhar tudo no corpo do contrato?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Pode usar anexos ou propostas para detalhar escopo e entregas, desde que fique claro como esses documentos se integram ao contrato.\"}},{\"@type\":\"Question\",\"name\":\"O gerador substitui advogado?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não em casos que exigem análise jurídica. Ele organiza uma minuta e ajuda a não esquecer informações essenciais.\"}}]}</script>', 1, 'Gestão Contábil', 'blog/covers/como-fazer-contrato-gerador-contratos.png', 'Ilustração do guia: Como fazer um contrato: cláusulas, revisão e assinatura', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:58', 'como fazer um contrato', '[\"gerador de contratos\", \"contrato prestação de serviços\", \"contrato compra e venda\", \"modelo de contrato\"]', 'Contrato de prestação de serviços: guia', 'Veja cláusulas essenciais de contrato de prestação de serviços: escopo, preço, prazo, aceite, rescisão, confidencialidade e responsabilidades.', NULL, 'blog/covers/como-fazer-contrato-gerador-contratos.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:58'),
(29, NULL, 'Recibo de pagamento: como fazer e quais informações incluir', 'como-fazer-recibo-de-pagamento', 'Veja como preencher um recibo com pagador, recebedor, valor, data, motivo e forma de pagamento, evitando documentos genéricos difíceis de comprovar depois.', '<p>Um recibo serve para registrar que determinado valor foi recebido por determinada pessoa ou empresa, em uma data e por uma finalidade. O documento perde muita utilidade quando diz apenas “recebi a importância acima” sem identificar a origem do pagamento, a relação com serviço, parcela ou obrigação e quem efetivamente recebeu.</p><p>O emissor deve privilegiar rastreabilidade: cada informação precisa ajudar alguém a entender o pagamento meses depois, sem depender da memória das partes.</p><div class=\"alert alert-info\"><strong>Em resumo:</strong> este guia mostra como analisar recibo de pagamento com memória de cálculo e premissas explícitas. Use os exemplos para entender a lógica e confirme regras variáveis antes de uma obrigação oficial.</div><h2>Identifique as partes</h2><p>Informe quem pagou e quem recebeu com os dados necessários à finalidade do documento. Para empresas, razão social e identificação pertinente podem ser úteis; para pessoas físicas, evite expor dados além do necessário.</p><p>O nome do recebedor no recibo deve ser coerente com quem reconhece a quitação.</p><h2>Descreva o motivo do pagamento</h2><p>Em vez de “serviços”, escreva algo como “parcela 2 de 4 referente ao serviço de desenvolvimento do site conforme contrato de 10/06/2026”. Uma descrição específica conecta o recibo à obrigação correta.</p><p>Se o pagamento quita apenas parte do valor, não use linguagem de quitação total.</p><h2>Valor, data e forma de pagamento</h2><p>Registre o valor em números e, quando desejado, por extenso, além da data em que o recebimento ocorreu. Informar PIX, transferência, dinheiro ou outro meio pode facilitar a reconciliação com extratos.</p><p>Se houver identificador de transação ou parcela, inclua-o em campo próprio ou observação.</p><h2>Exemplo de recibo bem descrito</h2><p>Um recibo de R$ 1.500 pode dizer que o valor corresponde à primeira parcela do serviço X, recebido em 27/07/2026 por PIX. Essa linha já permite relacionar documento, contrato e extrato.</p><p>Um recibo que diz apenas “R$ 1.500 por serviços prestados” exige investigação futura para descobrir a que se referia.</p><h2>Recibo não substitui outros documentos automaticamente</h2><p>Dependendo da operação, podem existir obrigações de nota fiscal, documento fiscal, retenções ou registros adicionais. O recibo comprova o recebimento descrito, mas não deve ser usado para substituir documentos exigidos em outra obrigação.</p><p>Guarde o recibo junto do comprovante financeiro e do documento que originou a cobrança quando aplicável.</p><h2>Como usar a ferramenta do Prazzu Tools</h2><p>Abra a ferramenta, informe os dados do seu cenário e revise a memória apresentada antes de salvar o resultado. Se estiver comparando alternativas, altere uma premissa de cada vez para entender o efeito real de cada variável.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça o cálculo no Prazzu Tools</h2><p>Use a ferramenta para transformar os dados deste guia em um cenário conferível, com resultado e memória organizados.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/emissor-de-recibos\">Abrir a ferramenta</a></div></div><p><strong>Continue a análise:</strong> veja também <a href=\"/ferramentas/gerador-de-contratos\">gerador de contratos</a> e <a href=\"/ferramentas/declaracao-rendimentos\">declaração de rendimentos</a>.</p><h2>Perguntas frequentes</h2><h3>Recibo é a mesma coisa que nota fiscal?</h3><p>Não. São documentos com finalidades diferentes; a existência de recibo não elimina automaticamente obrigações fiscais.</p><h3>Precisa ter assinatura?</h3><p>A assinatura ou forma de validação do recebedor aumenta a utilidade do documento, conforme o meio e a finalidade.</p><h3>Posso emitir recibo de pagamento parcial?</h3><p>Sim, mas deixe explícito que se trata de parcela ou pagamento parcial e identifique a obrigação correspondente.</p><h2>Conclusão</h2><p>Recibo de pagamento é mais útil quando o resultado pode ser reproduzido e explicado. Em vez de depender de um percentual genérico ou de um número isolado, registre bases, datas e premissas, compare cenários e use a ferramenta como apoio à análise. Quando houver efeito fiscal, trabalhista, previdenciário ou jurídico, confirme a regra vigente e os dados oficiais antes de executar a decisão.</p><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Recibo é a mesma coisa que nota fiscal?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não. São documentos com finalidades diferentes; a existência de recibo não elimina automaticamente obrigações fiscais.\"}},{\"@type\":\"Question\",\"name\":\"Precisa ter assinatura?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A assinatura ou forma de validação do recebedor aumenta a utilidade do documento, conforme o meio e a finalidade.\"}},{\"@type\":\"Question\",\"name\":\"Posso emitir recibo de pagamento parcial?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim, mas deixe explícito que se trata de parcela ou pagamento parcial e identifique a obrigação correspondente.\"}}]}</script>', 1, 'Gestão Contábil', 'blog/covers/como-fazer-recibo-de-pagamento.png', 'Ilustração do guia: Como fazer recibo de pagamento: dados, valor e assinatura', 'published', 0, '2026-07-27 13:45:49', '2026-07-27 14:06:58', 'como fazer recibo de pagamento', '[\"emissor de recibos\", \"modelo recibo pagamento\", \"recibo valor por extenso\", \"recibo simples\"]', 'Recibo de pagamento: como preencher', 'Aprenda a fazer recibo de pagamento com valor, data, pagador, recebedor, finalidade e assinatura, além de cuidados para manter rastreabilidade.', NULL, 'blog/covers/como-fazer-recibo-de-pagamento.png', 1, '2026-07-27 13:45:49', '2026-07-27 14:06:58'),
(30, NULL, 'Salário líquido 2026: como calcular INSS e IRRF passo a passo', 'salario-liquido-2026-como-calcular-inss-irrf', 'Aprenda a calcular salário líquido em 2026 com INSS progressivo, IRRF, redução mensal, dependentes e outros descontos da folha.', '<p>Saber quanto do salário bruto realmente chega à conta exige separar remuneração, contribuições previdenciárias, imposto de renda e descontos particulares. Em 2026, esse cálculo merece atenção extra porque a tabela do INSS foi atualizada e o IRRF passou a ter uma redução mensal específica para rendimentos tributáveis de até R$ 7.350,00.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> para calcular o salário líquido em 2026, comece pela remuneração tributável, calcule o INSS progressivamente, compare as deduções legais com o desconto simplificado do IRRF quando aplicável e só depois desconte vale-transporte, pensão e outros itens.</div><h2>O que é salário líquido</h2><p>Salário líquido é o valor efetivamente recebido depois dos descontos incidentes sobre a remuneração. Ele não é obtido aplicando uma única porcentagem sobre o salário bruto. O valor muda conforme a faixa previdenciária, a base do IRRF, dependentes, pensão alimentícia, benefícios descontados e outros eventos da folha.</p><h2>Tabela do INSS do empregado em 2026</h2><p>A contribuição do empregado é progressiva. Isso significa que cada faixa do salário de contribuição é tributada pela alíquota correspondente, e não que todo o salário seja multiplicado pela alíquota da última faixa alcançada.</p><ul><li>Até R$ 1.621,00: 7,5%.</li><li>De R$ 1.621,01 a R$ 2.902,84: 9%.</li><li>De R$ 2.902,85 a R$ 4.354,27: 12%.</li><li>De R$ 4.354,28 a R$ 8.475,55: 14%.</li><li>Acima do teto previdenciário, a contribuição do empregado fica limitada ao valor máximo resultante das faixas.</li></ul><p>Um erro comum é olhar a última faixa e multiplicar todo o salário por 14%. Isso superestima o desconto. O correto é somar a contribuição calculada em cada faixa.</p><h2>Como funciona o IRRF mensal em 2026</h2><p>Depois da contribuição previdenciária, é preciso determinar a base do imposto de renda. A Receita Federal mantém a tabela progressiva mensal e, a partir de janeiro de 2026, aplica uma redução adicional do imposto para rendimentos tributáveis sujeitos à incidência mensal.</p><ul><li>Base de cálculo até R$ 2.428,80: isenta pela tabela progressiva.</li><li>De R$ 2.428,81 a R$ 2.826,65: 7,5%, com parcela a deduzir de R$ 182,16.</li><li>De R$ 2.826,66 a R$ 3.751,05: 15%, com dedução de R$ 394,16.</li><li>De R$ 3.751,06 a R$ 4.664,68: 22,5%, com dedução de R$ 675,49.</li><li>Acima de R$ 4.664,68: 27,5%, com dedução de R$ 908,73.</li><li>Dedução mensal por dependente em 2026: R$ 189,59.</li><li>Limite mensal do desconto simplificado: R$ 607,20.</li></ul><p>Além da tabela progressiva, rendimentos tributáveis de até R$ 5.000,00 podem ter redução suficiente para zerar o imposto devido. Entre R$ 5.000,01 e R$ 7.350,00, a redução diminui gradualmente. Por isso, dois trabalhadores com salários próximos podem ter diferenças relevantes no IRRF.</p><h2>Passo a passo para calcular salário líquido</h2><ol><li>Some salário-base e demais verbas tributáveis do mês.</li><li>Determine o salário de contribuição e calcule o INSS de forma progressiva.</li><li>Identifique as deduções legais permitidas no IRRF, como INSS, dependentes e pensão quando cabível.</li><li>Compare, quando permitido, as deduções legais com o desconto simplificado mensal e use a alternativa aplicável mais vantajosa.</li><li>Calcule o IRRF pela tabela progressiva.</li><li>Aplique a redução mensal do imposto prevista para 2026, quando o rendimento estiver dentro da faixa.</li><li>Subtraia vale-transporte, benefícios coparticipados, adiantamentos e outros descontos da folha.</li><li>Confira se adicionais ou verbas indenizatórias foram classificados corretamente antes de fechar o valor líquido.</li></ol><h2>Exemplo: salário bruto de R$ 5.000,00</h2><p>Em um cenário simples, sem dependentes e sem outros descontos, o cálculo deve observar o INSS progressivo e a forma mais vantajosa de dedução do IRRF. Em 2026, a Receita Federal publicou exemplo oficial mostrando que, para rendimento tributável de R$ 5.000,00, a redução mensal pode zerar o IRRF depois da aplicação da tabela progressiva. O resultado líquido ainda dependerá do INSS e de outros descontos existentes na folha.</p><h2>O que pode fazer o valor líquido mudar</h2><ul><li>Horas extras, adicional noturno, comissões e gratificações.</li><li>Número de dependentes informados para o IRRF.</li><li>Pensão alimentícia dedutível nas hipóteses legais.</li><li>Vale-transporte e coparticipações em benefícios.</li><li>Faltas, atrasos, adiantamentos e descontos autorizados.</li><li>Existência de mais de um vínculo empregatício, especialmente para a contribuição previdenciária.</li><li>Verbas não tributáveis ou indenizatórias, que precisam ser separadas das verbas salariais.</li></ul><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-salario-liquido\">Calcular salário líquido</a></div></div><h2>Perguntas frequentes</h2><h3>Quem ganha R$ 5.000 paga IRRF em 2026?</h3><p>A Receita Federal informa que a redução mensal pode zerar o IRRF para rendimentos tributáveis de até R$ 5.000,00. Isso não significa que o salário líquido seja R$ 5.000,00, pois o INSS e outros descontos continuam podendo existir.</p><h3>INSS é calculado sobre o salário inteiro pela maior alíquota?</h3><p>Não. Para empregado, empregado doméstico e trabalhador avulso, o INSS é progressivo por faixas. Cada parte do salário é alcançada pela alíquota da respectiva faixa.</p><h3>Salário líquido e salário-base são a mesma coisa?</h3><p>Não. Salário-base é uma parcela contratual da remuneração. Salário líquido é o total final depois de proventos e descontos.</p><h2>Conclusão</h2><p>O cálculo correto do salário líquido em 2026 exige trabalhar com as tabelas vigentes e mostrar claramente de onde veio cada desconto. Evite estimativas por porcentagem única. Para conferência de folha, use memória de cálculo e valide a competência, as verbas e as deduções antes de tomar o valor como definitivo.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/tabelas/2026\" rel=\"nofollow noopener\" target=\"_blank\">Receita Federal — Tributação de 2026</a></li><li><a href=\"https://www.gov.br/inss/pt-br/direitos-e-deveres/inscricao-e-contribuicao/tabela-de-contribuicao-mensal\" rel=\"nofollow noopener\" target=\"_blank\">INSS — Tabela de contribuição mensal</a></li></ul>', 4, 'Trabalhista', 'blog/covers/salario-liquido-2026.png', 'Ilustração sobre cálculo de salário líquido 2026 com INSS e IRRF', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'salário líquido 2026', '[\"calculadora salário líquido\", \"INSS 2026\", \"IRRF 2026\", \"salário bruto para líquido\", \"quanto vou receber líquido\"]', 'Salário líquido 2026: calcule INSS e IRRF', 'Veja como calcular salário líquido em 2026 com INSS progressivo, IRRF, redução mensal, dependentes e descontos. Confira o passo a passo.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04');
INSERT INTO `blog_posts` (`id`, `author_id`, `title`, `slug`, `excerpt`, `content`, `category_id`, `category`, `cover_image_path`, `cover_image_alt`, `status`, `is_featured`, `published_at`, `content_updated_at`, `primary_keyword`, `related_keywords`, `meta_title`, `meta_description`, `canonical_url`, `social_image_path`, `should_index`, `created_at`, `updated_at`) VALUES
(31, NULL, 'Salário bruto x líquido: entenda a diferença e quanto realmente cai na conta', 'salario-bruto-x-liquido-diferenca', 'Entenda a diferença entre salário bruto e líquido, quais descontos reduzem o pagamento e como comparar propostas de emprego com segurança.', '<p>Salário bruto e salário líquido aparecem juntos no contracheque, mas representam coisas diferentes. O bruto mostra a remuneração antes dos descontos; o líquido mostra o que efetivamente será pago ao trabalhador. Entender essa diferença ajuda a comparar propostas de emprego, revisar a folha e planejar o orçamento mensal.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> não use uma porcentagem fixa para converter salário bruto em líquido. O resultado depende das faixas de INSS e IRRF, das verbas do mês e dos descontos pessoais.</div><h2>Salário bruto: o valor antes dos descontos</h2><p>O salário bruto costuma partir do salário-base e pode receber adicionais, horas extras, comissões, gratificações e outras verbas. Nem toda parcela tem o mesmo tratamento tributário, por isso é importante identificar a natureza de cada verba antes de calcular encargos e retenções.</p><h2>Salário líquido: o valor que chega à conta</h2><p>O líquido resulta da remuneração do mês menos os descontos. Entre os mais comuns estão INSS, IRRF, vale-transporte, pensão alimentícia, adiantamentos, faltas, coparticipação em benefícios e descontos autorizados.</p><h2>Por que não existe uma tabela única de bruto para líquido</h2><p>Uma pessoa com salário bruto de R$ 4.000,00 pode receber líquido diferente de outra com o mesmo bruto. Dependentes, pensão, vale-transporte, benefícios, horas extras e outras verbas alteram a base e o resultado. Além disso, a contribuição previdenciária é progressiva e o imposto de renda tem deduções e redução mensal.</p><h2>Como comparar uma proposta de emprego</h2><ol><li>Separe salário-base de bônus e remuneração variável.</li><li>Confirme quais benefícios são pagos pela empresa e quais têm coparticipação.</li><li>Estime INSS e IRRF pela competência correta.</li><li>Inclua descontos recorrentes, como vale-transporte ou plano de saúde.</li><li>Não confunda FGTS com desconto do empregado: o depósito de FGTS é obrigação do empregador e não reduz o líquido diretamente.</li><li>Se houver comissão ou hora extra frequente, simule mais de um mês para entender a variação.</li></ol><h2>Bruto, remuneração e custo da empresa não são sinônimos</h2><p>Outra confusão frequente é comparar salário bruto com custo total do empregado. O custo empresarial inclui parcelas que não são descontadas do trabalhador, como FGTS e encargos patronais aplicáveis. Por isso, o valor que custa para a empresa pode ser significativamente maior que o salário bruto, enquanto o valor recebido pelo empregado é menor por causa das retenções.</p><h2>Exemplo prático de leitura do contracheque</h2><p>Imagine um empregado com salário-base, algumas horas extras e vale-transporte. Primeiro, as horas extras entram nos proventos. Depois, as verbas tributáveis alimentam as bases previdenciária e fiscal conforme as regras aplicáveis. Por fim, são subtraídos INSS, eventual IRRF e demais descontos. A última linha da folha é o líquido a pagar.</p><h2>Erros comuns ao estimar salário líquido</h2><ul><li>Aplicar 14% de INSS sobre o salário inteiro.</li><li>Aplicar 27,5% de IRRF diretamente sobre o salário bruto.</li><li>Ignorar a redução do IRRF vigente em 2026.</li><li>Tratar FGTS como desconto do trabalhador.</li><li>Esquecer benefícios com coparticipação.</li><li>Comparar uma proposta mensal sem considerar remuneração variável e descontos recorrentes.</li></ul><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-salario-liquido\">Converter bruto em líquido</a></div></div><h2>Perguntas frequentes</h2><h3>FGTS diminui o salário líquido?</h3><p>O depósito normal de FGTS é feito pelo empregador e não é descontado do salário do empregado. Ele compõe o custo empresarial, não a retenção direta que reduz o líquido.</p><h3>Quanto dá líquido um salário de R$ 3.000?</h3><p>Não há um único valor sem conhecer a competência e os descontos do trabalhador. Em 2026, o cálculo deve usar a tabela progressiva do INSS e as regras mensais do IRRF, além dos descontos particulares da folha.</p><h3>Vale-transporte sempre desconta 6%?</h3><p>O tratamento depende do benefício efetivamente concedido e das regras aplicáveis ao caso. Na conferência da folha, use o valor real informado e não presuma um desconto sem verificar a situação do empregado.</p><h2>Conclusão</h2><p>A melhor forma de comparar salário bruto e líquido é abrir a memória do cálculo. Quando INSS, IRRF e descontos aparecem separados, fica mais fácil conferir a folha, negociar uma proposta e entender por que o valor recebido mudou de um mês para outro.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/tabelas/2026\" rel=\"nofollow noopener\" target=\"_blank\">Receita Federal — Tributação de 2026</a></li><li><a href=\"https://www.gov.br/inss/pt-br/direitos-e-deveres/inscricao-e-contribuicao/tabela-de-contribuicao-mensal\" rel=\"nofollow noopener\" target=\"_blank\">INSS — Tabela de contribuição mensal</a></li></ul>', 4, 'Trabalhista', 'blog/covers/salario-liquido-2026.png', 'Ilustração comparando salário bruto e salário líquido', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'salário bruto e líquido', '[\"salário bruto para líquido\", \"quanto cai na conta\", \"descontos no salário\", \"calculadora de salário\", \"contracheque\"]', 'Salário bruto x líquido: qual é a diferença?', 'Entenda salário bruto e líquido, quais descontos entram na folha e como estimar quanto realmente cai na conta sem usar porcentagens erradas.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04'),
(32, NULL, 'INSS e IRRF 2026 no salário: tabelas, descontos e exemplos práticos', 'inss-irrf-2026-salario-tabelas-descontos', 'Confira as tabelas de INSS e IRRF de 2026, entenda o cálculo progressivo e veja como a redução mensal do imposto afeta o salário.', '<p>INSS e IRRF são dois dos principais descontos que aparecem na folha, mas possuem bases e regras diferentes. Em 2026, a tabela previdenciária do empregado foi atualizada e o imposto de renda mensal passou a contar com uma redução específica conforme o rendimento tributável.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> INSS e IRRF não devem ser calculados com a mesma base nem com uma alíquota única. O INSS do empregado é progressivo por faixas; o IRRF depende da base após deduções e pode receber a redução mensal de 2026.</div><h2>INSS 2026: faixas para empregado</h2><ul><li>Até R$ 1.621,00: 7,5%.</li><li>De R$ 1.621,01 a R$ 2.902,84: 9%.</li><li>De R$ 2.902,85 a R$ 4.354,27: 12%.</li><li>De R$ 4.354,28 a R$ 8.475,55: 14%.</li></ul><p>Como o cálculo é progressivo, apenas a parcela do salário dentro de cada faixa recebe a respectiva alíquota. Ao alcançar o teto previdenciário, a contribuição deixa de crescer por remuneração adicional sujeita ao mesmo limite.</p><h2>IRRF 2026: tabela progressiva mensal</h2><ul><li>Até R$ 2.428,80 de base: sem imposto pela tabela.</li><li>R$ 2.428,81 a R$ 2.826,65: 7,5% e dedução de R$ 182,16.</li><li>R$ 2.826,66 a R$ 3.751,05: 15% e dedução de R$ 394,16.</li><li>R$ 3.751,06 a R$ 4.664,68: 22,5% e dedução de R$ 675,49.</li><li>Acima de R$ 4.664,68: 27,5% e dedução de R$ 908,73.</li></ul><h2>A redução do IRRF em 2026</h2><p>A partir de janeiro de 2026, a legislação passou a prever redução do imposto mensal. Para rendimentos tributáveis de até R$ 5.000,00, a redução pode levar o imposto devido a zero. Entre R$ 5.000,01 e R$ 7.350,00, a redução é decrescente até chegar a zero acima do limite.</p><p>A Receita Federal publicou exemplos mostrando que um rendimento tributável de R$ 5.000,00 pode ter IRRF zerado após a redução, enquanto um rendimento de R$ 6.000,00 ainda pode ter imposto devido, porém menor do que seria sem a redução.</p><h2>Deduções legais e desconto simplificado mensal</h2><p>Na determinação da base do IRRF, podem existir deduções legais permitidas, como contribuição previdenciária, dependentes e pensão alimentícia nas hipóteses legais. O desconto simplificado mensal possui limite de R$ 607,20 em 2026 e pode substituir as deduções legais quando for a alternativa aplicável e mais vantajosa.</p><h2>Por que a competência importa</h2><p>Tabelas tributárias mudam. Um cálculo referente a janeiro de 2026 não deve usar valores de 2025, e uma folha antiga precisa manter a regra vigente na competência original. Sistemas e planilhas devem registrar a data de referência para que o cálculo possa ser auditado depois.</p><h2>Checklist para conferir INSS e IRRF</h2><ol><li>Confirme a competência da folha.</li><li>Separe verbas tributáveis de verbas sem incidência conforme o caso.</li><li>Calcule o INSS progressivamente.</li><li>Confira deduções legais e eventual desconto simplificado do IRRF.</li><li>Aplique a tabela progressiva mensal.</li><li>Aplique a redução mensal de 2026 quando cabível.</li><li>Compare o resultado com a memória do sistema de folha antes de alterar manualmente qualquer valor.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-salario-liquido\">Simular INSS, IRRF e líquido</a></div></div><h2>Perguntas frequentes</h2><h3>A alíquota de 27,5% do IRRF incide sobre todo o salário?</h3><p>Não. A alíquota é aplicada sobre a base de cálculo do imposto, e a própria tabela prevê parcela a deduzir. Além disso, em 2026 pode existir redução posterior do imposto conforme o rendimento tributável.</p><h3>O desconto simplificado de R$ 607,20 é um desconto no salário?</h3><p>Não. Ele é uma dedução usada para determinar a base do IRRF quando aplicável. Não representa um valor pago ao empregado ou descontado isoladamente do líquido.</p><h3>Quem tem dois empregos deve somar os salários para o INSS?</h3><p>O INSS orienta que remunerações de vínculos concomitantes sejam consideradas em conjunto para aplicação da contribuição mensal, respeitado o teto. A operacionalização deve observar os dados e documentos do trabalhador.</p><h2>Conclusão</h2><p>INSS e IRRF precisam ser tratados como cálculos distintos e versionados. Em 2026, conferir a progressividade do INSS e a redução mensal do imposto de renda é essencial para evitar desconto incorreto e explicar o salário líquido ao trabalhador.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/tabelas/2026\" rel=\"nofollow noopener\" target=\"_blank\">Receita Federal — Tributação de 2026</a></li><li><a href=\"https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/tabelas/exemplos-de-aplicacao-da-lei-15-270-2025\" rel=\"nofollow noopener\" target=\"_blank\">Receita Federal — Exemplos da Lei 15.270/2025</a></li><li><a href=\"https://www.gov.br/inss/pt-br/direitos-e-deveres/inscricao-e-contribuicao/tabela-de-contribuicao-mensal\" rel=\"nofollow noopener\" target=\"_blank\">INSS — Tabela de contribuição mensal</a></li></ul>', 4, 'Trabalhista', 'blog/covers/salario-liquido-2026.png', 'Ilustração sobre tabelas de INSS e IRRF 2026 aplicadas ao salário', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'INSS e IRRF 2026', '[\"tabela INSS 2026\", \"tabela IRRF 2026\", \"desconto INSS salário\", \"desconto imposto de renda salário\", \"salário líquido 2026\"]', 'INSS e IRRF 2026: tabelas e cálculo no salário', 'Veja as tabelas de INSS e IRRF 2026, entenda faixas progressivas, deduções e a redução mensal do imposto com exemplos práticos.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04'),
(33, NULL, 'Como calcular hora extra 50% e 100%: fórmula, exemplos e cuidados', 'como-calcular-hora-extra-50-100', 'Aprenda a calcular hora extra de 50% e 100%, descobrir o valor da hora, escolher o divisor correto e conferir reflexos no DSR.', '<p>Calcular hora extra corretamente exige descobrir primeiro o valor da hora normal e depois aplicar o adicional devido. Para a regra geral da CLT, a remuneração da hora extraordinária deve ter acréscimo de pelo menos 50% sobre a hora normal, sem prejuízo de percentuais maiores previstos em acordo, convenção coletiva ou situação específica.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> para calcular hora extra, divida o salário mensal pelo divisor aplicável à jornada, encontre o valor da hora normal e multiplique pela hora extra com o adicional correspondente. Antes de fechar a folha, confira norma coletiva e regime de jornada.</div><h2>Fórmula básica da hora extra</h2><p>Em um cenário comum de empregado mensalista com divisor 220, o valor da hora normal pode ser obtido dividindo o salário-base mensal por 220. A hora extra de 50% corresponde à hora normal multiplicada por 1,5. A hora extra de 100% corresponde à hora normal multiplicada por 2.</p><h2>Exemplo de hora extra 50%</h2><p>Considere salário de R$ 2.200,00 e divisor 220. A hora normal vale R$ 10,00. Uma hora extra com adicional de 50% vale R$ 15,00. Se o empregado fizer 10 horas nessas condições, o total das horas extras será R$ 150,00 antes de reflexos e outras incidências.</p><h2>Exemplo de hora extra 100%</h2><p>Com a mesma hora normal de R$ 10,00, uma hora extra de 100% vale R$ 20,00. O percentual de 100% não deve ser presumido para toda situação: feriados, domingos, compensações e normas coletivas podem alterar o tratamento.</p><h2>Qual divisor usar</h2><p>O divisor depende da jornada contratual e do regime aplicável. O divisor 220 é comum em jornadas de 44 horas semanais, mas não serve para todos os empregados. Jornadas de 40, 36 ou 30 horas, por exemplo, podem exigir outro divisor. A conferência do contrato e da norma coletiva vem antes da fórmula.</p><h2>Hora extra habitual e DSR</h2><p>Horas extraordinárias prestadas habitualmente repercutem no repouso remunerado. Em 2025, o Tribunal Superior do Trabalho reafirmou em tema repetitivo a incidência das horas extras habituais no cálculo do repouso remunerado, em linha com a Súmula 172.</p><h2>O que deve ser conferido antes do cálculo</h2><ul><li>Salário e base remuneratória que compõem a hora normal.</li><li>Jornada contratual e divisor aplicável.</li><li>Quantidade real de horas extraordinárias.</li><li>Percentual mínimo legal e eventual percentual superior da norma coletiva.</li><li>Existência de banco de horas ou compensação válida.</li><li>Horas realizadas em período noturno.</li><li>Reflexos e incidências aplicáveis à habitualidade.</li></ul><h2>Erros comuns</h2><ul><li>Usar divisor 220 para qualquer jornada.</li><li>Somar apenas o adicional de 50% e esquecer de remunerar a hora normal extraordinária.</li><li>Tratar toda hora em domingo como automaticamente 100% sem verificar compensação e norma aplicável.</li><li>Ignorar adicional noturno quando a hora extra ocorre no período noturno.</li><li>Calcular DSR com quantidade de dias errada.</li><li>Alterar manualmente o resultado sem guardar a memória de cálculo.</li></ul><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-hora-extra\">Calcular hora extra</a></div></div><h2>Perguntas frequentes</h2><h3>Hora extra é sempre 50%?</h3><p>A CLT prevê adicional mínimo de 50% na regra geral. Percentual superior pode decorrer de instrumento coletivo, contrato ou situação específica.</p><h3>Hora extra 100% é sempre obrigatória no domingo?</h3><p>Não é seguro presumir isso isoladamente. É necessário verificar repouso, compensação, feriado, escala e norma coletiva aplicável ao empregado.</p><h3>O DSR entra no valor da hora extra?</h3><p>O reflexo de horas extras habituais no repouso remunerado é calculado separadamente, de acordo com o período e os critérios aplicáveis.</p><h2>Conclusão</h2><p>A fórmula da hora extra é simples apenas quando as premissas estão corretas. Divisor, percentual, jornada, período noturno e DSR precisam estar explícitos para que a folha seja conferível e o resultado possa ser reproduzido.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.planalto.gov.br/ccivil_03/decreto-lei/del5452compilado.htm\" rel=\"nofollow noopener\" target=\"_blank\">CLT — jornada e trabalho noturno</a></li><li><a href=\"https://www.tst.jus.br/documents/d/guest/irr256temprandomsuffixfyalrpeo\" rel=\"nofollow noopener\" target=\"_blank\">TST — Tema 256 sobre horas extras habituais e repouso remunerado</a></li></ul>', 4, 'Trabalhista', 'blog/covers/hora-extra-adicional-noturno-dsr.png', 'Ilustração sobre cálculo de hora extra 50% e 100%', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'calcular hora extra', '[\"calculadora hora extra\", \"hora extra 50%\", \"hora extra 100%\", \"valor da hora trabalhada\", \"divisor 220\"]', 'Como calcular hora extra 50% e 100% passo a passo', 'Aprenda a calcular hora extra de 50% e 100%, encontrar o valor da hora, usar o divisor correto e conferir reflexos no DSR.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04'),
(34, NULL, 'Adicional noturno: como calcular a hora reduzida de 52min30s e as horas extras', 'adicional-noturno-como-calcular-hora-reduzida', 'Entenda o adicional noturno de 20%, a hora reduzida de 52min30s, o período das 22h às 5h e como tratar hora extra noturna.', '<p>O trabalho noturno urbano possui regras próprias na CLT. Na regra geral, o período entre 22h e 5h recebe adicional de pelo menos 20% sobre a hora diurna e a hora noturna é computada como 52 minutos e 30 segundos. Esses dois elementos precisam ser tratados separadamente no cálculo.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> adicional noturno não é apenas multiplicar as horas por 20%. Em muitos casos é necessário considerar também a hora noturna reduzida e verificar se existem prorrogações, jornada mista ou regras coletivas diferentes.</div><h2>Qual é o horário noturno urbano</h2><p>Para o trabalhador urbano regido pela regra geral do art. 73 da CLT, considera-se noturno o trabalho realizado entre 22 horas de um dia e 5 horas do dia seguinte.</p><h2>Qual é o percentual do adicional noturno</h2><p>A CLT estabelece acréscimo de pelo menos 20% sobre a hora diurna. Convenções ou acordos coletivos podem prever percentual maior. Por isso, a folha deve registrar a origem do percentual usado.</p><h2>O que é hora noturna reduzida</h2><p>A hora do trabalho noturno urbano é computada como 52 minutos e 30 segundos. Isso significa que sete horas de relógio entre 22h e 5h representam oito horas noturnas reduzidas para fins da regra legal. A conversão precisa ser feita antes de aplicar valores quando o cenário exigir.</p><h2>Exemplo simplificado</h2><p>Se a hora diurna vale R$ 10,00 e o adicional noturno aplicável é 20%, a parcela de adicional corresponde a R$ 2,00 por hora noturna considerada. O total do período depende da quantidade de horas noturnas convertidas e de outros eventos, como horas extras.</p><h2>Hora extra noturna</h2><p>Quando uma hora extraordinária ocorre dentro do período noturno, podem coexistir adicional de hora extra e adicional noturno. A ordem e a base do cálculo devem seguir a legislação e a norma coletiva aplicável, evitando somar percentuais de maneira informal.</p><h2>Prorrogação da jornada noturna</h2><p>A CLT prevê aplicação das regras do trabalho noturno às prorrogações, e a jurisprudência trabalhista possui entendimentos específicos conforme a jornada. Esse é um ponto em que o cálculo deve ser confrontado com o caso concreto e a norma coletiva, especialmente em escalas.</p><h2>Checklist para o departamento pessoal</h2><ol><li>Identifique se a regra urbana do art. 73 é realmente a aplicável.</li><li>Confirme o período efetivamente trabalhado.</li><li>Converta a hora noturna reduzida quando cabível.</li><li>Confirme o percentual legal ou coletivo.</li><li>Separe horas normais noturnas de horas extras noturnas.</li><li>Verifique reflexos e incidências da verba.</li><li>Guarde a memória de cálculo usada na folha.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-hora-extra\">Calcular adicional noturno</a></div></div><h2>Perguntas frequentes</h2><h3>A hora noturna tem 60 minutos?</h3><p>Para a regra urbana do art. 73 da CLT, a hora noturna é computada como 52 minutos e 30 segundos.</p><h3>O adicional noturno é sempre 20%?</h3><p>Vinte por cento é o mínimo legal da regra geral urbana. Instrumento coletivo pode estabelecer percentual superior, e outras categorias possuem regras específicas.</p><h3>Quem trabalha depois das 5h perde o adicional automaticamente?</h3><p>A prorrogação do trabalho noturno merece análise própria. Não é recomendável cortar o adicional apenas olhando o relógio sem verificar jornada, regra legal e entendimento aplicável ao caso.</p><h2>Conclusão</h2><p>O adicional noturno combina percentual, horário e hora reduzida. Quando também existem horas extras, a conferência precisa mostrar cada etapa. A memória de cálculo evita que um percentual correto seja aplicado sobre uma quantidade de horas errada.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.planalto.gov.br/ccivil_03/decreto-lei/del5452compilado.htm\" rel=\"nofollow noopener\" target=\"_blank\">CLT — art. 73 e trabalho noturno</a></li><li><a href=\"https://www3.tst.jus.br/jurisprudencia/Sumulas_com_indice/Sumulas_Ind_51_100.html\" rel=\"nofollow noopener\" target=\"_blank\">TST — Súmula 65 e hora noturna reduzida</a></li></ul>', 4, 'Trabalhista', 'blog/covers/hora-extra-adicional-noturno-dsr.png', 'Ilustração sobre adicional noturno, hora reduzida e jornada noturna', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'adicional noturno', '[\"calculadora adicional noturno\", \"hora noturna reduzida\", \"52 minutos e 30 segundos\", \"hora extra noturna\", \"trabalho noturno CLT\"]', 'Adicional noturno: como calcular a hora reduzida', 'Veja como calcular adicional noturno, hora reduzida de 52min30s, período das 22h às 5h e hora extra noturna com exemplos.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04'),
(35, NULL, 'DSR sobre horas extras: como calcular, fórmula e exemplo prático', 'dsr-sobre-horas-extras-como-calcular', 'Veja como funciona o DSR sobre horas extras, por que dias úteis e repousos alteram o resultado e como conferir o cálculo na folha.', '<p>O DSR sobre horas extras é um dos pontos que mais gera dúvida na conferência da folha. A ideia central é que horas extraordinárias prestadas com habitualidade repercutem no repouso semanal remunerado. O cálculo precisa considerar os valores extras do período e a relação entre dias úteis e dias de repouso.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> não use uma fração fixa de 1/6 para qualquer folha mensal. O cálculo do DSR sobre variáveis normalmente depende da quantidade efetiva de dias úteis e de repousos/feriados do período, além da regra aplicável ao empregado.</div><h2>O que é DSR</h2><p>DSR é o descanso semanal remunerado. A Lei 605 garante o repouso remunerado e prevê, para trabalhadores por hora, o cômputo das horas extraordinárias habitualmente prestadas na remuneração do repouso.</p><h2>Horas extras entram no DSR?</h2><p>Sim, quando habituais, conforme a regra consolidada. Em 2025, o TST reafirmou em julgamento repetitivo que as horas extraordinárias habitualmente prestadas são computadas no cálculo do repouso remunerado, com referência à Súmula 172.</p><h2>Fórmula usada em muitos cenários mensais</h2><p>Uma forma comum de apuração de parcelas variáveis é dividir o total das horas extras remuneradas pelos dias úteis do período e multiplicar pelos domingos e feriados considerados como repouso. A parametrização, porém, precisa refletir calendário, jornada e regra aplicável. Sistemas não devem esconder quantos dias foram usados.</p><h2>Exemplo simples</h2><p>Se as horas extras remuneradas do período somam R$ 300,00, o calendário considerado tem 25 dias úteis e 5 repousos/feriados, um exemplo matemático seria R$ 300,00 ÷ 25 × 5 = R$ 60,00 de reflexo. Esse exemplo demonstra a lógica, mas a folha real deve usar a contagem correta do período e as particularidades do vínculo.</p><h2>Por que o calendário faz diferença</h2><p>Meses com quantidades diferentes de domingos, feriados e dias úteis podem produzir reflexos diferentes mesmo quando o total de horas extras é igual. Por isso, repetir um percentual padrão mês a mês pode gerar divergência.</p><h2>DSR e repercussões em outras parcelas</h2><p>O tratamento dos reflexos do DSR majorado por horas extras em outras parcelas trabalhistas sofreu evolução jurisprudencial e precisa ser observado conforme período e entendimento aplicável. Para rotinas de folha e passivo, evite transportar automaticamente um resultado sem conferir a competência e a norma vigente.</p><h2>Checklist de conferência</h2><ol><li>Some apenas as horas extras que pertencem ao período correto.</li><li>Confirme o valor de cada modalidade de hora extra.</li><li>Conte dias úteis conforme o critério adotado pela folha.</li><li>Conte domingos e feriados/repousos aplicáveis.</li><li>Calcule o reflexo e mantenha os números usados visíveis.</li><li>Verifique se norma coletiva estabelece tratamento específico.</li><li>Registre a competência para permitir auditoria futura.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-hora-extra\">Calcular horas extras e DSR</a></div></div><h2>Perguntas frequentes</h2><h3>DSR sobre hora extra é sempre 1/6?</h3><p>Não é recomendável usar 1/6 como regra universal. O resultado pode depender do calendário e da forma de apuração adotada para a verba variável.</p><h3>Feriado entra no cálculo?</h3><p>Feriados remunerados podem integrar a contagem de repousos conforme o cenário. O calendário e as regras da folha devem ser conferidos.</p><h3>Hora extra eventual gera o mesmo reflexo?</h3><p>A legislação e a jurisprudência tratam expressamente da habitualidade em vários contextos. O enquadramento da verba deve considerar a frequência e o caso concreto.</p><h2>Conclusão</h2><p>O DSR sobre horas extras fica mais seguro quando o cálculo mostra o total das horas extras, os dias úteis, os repousos e a fórmula utilizada. Esse nível de transparência facilita a conferência do departamento pessoal e reduz ajustes sem justificativa.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.planalto.gov.br/ccivil_03/leis/l0605.htm\" rel=\"nofollow noopener\" target=\"_blank\">Lei 605/1949 — repouso semanal remunerado</a></li><li><a href=\"https://www.tst.jus.br/documents/d/guest/irr256temprandomsuffixfyalrpeo\" rel=\"nofollow noopener\" target=\"_blank\">TST — Tema 256 sobre horas extras habituais e DSR</a></li></ul>', 4, 'Trabalhista', 'blog/covers/hora-extra-adicional-noturno-dsr.png', 'Ilustração sobre cálculo do DSR sobre horas extras', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'DSR sobre horas extras', '[\"calcular DSR\", \"reflexo de horas extras\", \"descanso semanal remunerado\", \"DSR folha de pagamento\", \"hora extra habitual\"]', 'DSR sobre horas extras: fórmula e exemplo de cálculo', 'Aprenda a calcular DSR sobre horas extras, entender dias úteis e repousos e conferir o reflexo na folha com exemplo prático.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04'),
(36, NULL, 'DIFAL ICMS: como calcular passo a passo com exemplo prático', 'difal-icms-como-calcular-passo-a-passo', 'Aprenda a calcular DIFAL do ICMS, identificar a alíquota interestadual, conferir alíquota interna, FCP e evitar erros na operação.', '<p>O DIFAL do ICMS aparece em operações interestaduais quando a legislação atribui ao estado de destino a diferença entre a carga interna e a interestadual. O cálculo parece simples, mas depende de pontos que precisam ser confirmados antes: origem, destino, natureza da mercadoria, alíquota interestadual, alíquota interna, FCP, responsabilidade e método de base aplicável.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> não calcule DIFAL apenas escolhendo duas UFs. A UF ajuda a determinar a alíquota interestadual, mas a alíquota interna e o FCP podem variar por produto, NCM, benefício e legislação do estado de destino.</div><h2>O que é DIFAL</h2><p>DIFAL é o diferencial de alíquotas do ICMS. Na operação interestadual alcançada pela regra, compara-se a carga interestadual com a carga interna do estado de destino para determinar o valor devido ao destino, observando a legislação aplicável ao caso.</p><h2>Quais dados você precisa antes de calcular</h2><ul><li>UF de origem e UF de destino.</li><li>Valor ou base de cálculo da operação.</li><li>Se o destinatário é contribuinte do ICMS.</li><li>Se a mercadoria se enquadra na alíquota interestadual de 4% para importados.</li><li>Alíquota interna aplicável ao produto no destino.</li><li>Percentual de FCP, quando houver.</li><li>Benefícios fiscais ou reduções de base.</li><li>Método de cálculo exigido pelo estado e pela operação.</li></ul><h2>Alíquota interestadual: 7%, 12% ou 4%</h2><p>A Resolução do Senado nº 22/1989 fixa 12% como regra interestadual geral e 7% nas operações e prestações realizadas das Regiões Sul e Sudeste destinadas às Regiões Norte, Nordeste e Centro-Oeste e ao Espírito Santo. A Resolução nº 13/2012 prevê 4% para determinadas operações interestaduais com bens e mercadorias importados do exterior.</p><h2>Exemplo de DIFAL com base simples</h2><p>Considere operação de São Paulo para Bahia com base de R$ 1.000,00, alíquota interna confirmada de 18% e interestadual de 7%. Em um exemplo de base simples, a diferença de alíquotas é 11 pontos percentuais, resultando em R$ 110,00 de DIFAL. Se houver FCP de 2% sobre a mesma base, o FCP seria R$ 20,00, totalizando R$ 130,00 destinados ao estado de destino no exemplo.</p><h2>Por que a alíquota interna não deve ser inferida apenas pela UF</h2><p>Um mesmo estado pode possuir alíquotas diferentes conforme mercadoria, serviço, NCM, essencialidade, benefício fiscal e período. A LC 190/2022 determina a disponibilização de informações estaduais relacionadas às regras do DIFAL, mas a conferência da operação específica continua indispensável.</p><h2>Quem recolhe o DIFAL</h2><p>A responsabilidade varia conforme o destinatário ser ou não contribuinte e conforme a hipótese legal. Em operações destinadas a consumidor final não contribuinte, a EC 87/2015 e a LC 190/2022 são referências centrais. Em outros cenários, a responsabilidade e a forma de recolhimento precisam ser verificadas.</p><h2>Base simples e base dupla</h2><p>Algumas rotinas fiscais trabalham com cálculo chamado de base dupla ou ICMS por dentro conforme interpretação e regulamentação aplicáveis ao caso. Não é seguro ativar essa forma de cálculo automaticamente para todas as operações. A ferramenta deve permitir simulação, mas o profissional precisa confirmar o método exigido pelo destino.</p><h2>Checklist antes de recolher</h2><ol><li>Confirme a operação e o destinatário.</li><li>Valide a alíquota interestadual.</li><li>Pesquise a alíquota interna específica do produto no destino.</li><li>Verifique FCP e sua base.</li><li>Cheque benefício, redução ou isenção.</li><li>Confirme responsabilidade e documento de recolhimento.</li><li>Registre as fontes e a competência utilizadas no cálculo.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-difal-icms\">Calcular DIFAL</a></div></div><h2>Perguntas frequentes</h2><h3>DIFAL é sempre alíquota interna menos 12%?</h3><p>Não. A alíquota interestadual pode ser 7%, 12% ou 4% em hipóteses específicas, e o cálculo pode envolver outras particularidades.</p><h3>FCP faz parte do DIFAL?</h3><p>O FCP pode ser devido adicionalmente conforme a legislação do estado de destino e do produto. Ele deve aparecer separado na memória para facilitar a conferência.</p><h3>Posso descobrir a alíquota interna só pela UF?</h3><p>Não com segurança. É necessário identificar o produto, a operação, eventuais benefícios e a legislação vigente.</p><h2>Conclusão</h2><p>Um cálculo de DIFAL confiável começa pela confirmação das premissas. Automatizar a matemática ajuda, mas alíquota interna, FCP, benefício e método de base devem permanecer auditáveis e vinculados à legislação da operação.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp190.htm\" rel=\"nofollow noopener\" target=\"_blank\">LC 190/2022 — DIFAL</a></li><li><a href=\"https://legis.senado.leg.br/norma/586152/publicacao?tipoDocumento=RSF&tipoTexto=ATU\" rel=\"nofollow noopener\" target=\"_blank\">Resolução do Senado 22/1989 — alíquotas interestaduais</a></li><li><a href=\"https://legis.senado.leg.br/norma/586999/publicacao?tipoDocumento=RSF&tipoTexto=ATU\" rel=\"nofollow noopener\" target=\"_blank\">Resolução do Senado 13/2012 — alíquota de 4% para importados</a></li></ul>', 3, 'Fiscal e Tributário', 'blog/covers/difal-icms-fcp.png', 'Ilustração sobre cálculo de DIFAL ICMS interestadual e FCP', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'calcular DIFAL', '[\"calculadora DIFAL\", \"DIFAL ICMS\", \"ICMS interestadual\", \"DIFAL consumidor final\", \"FCP DIFAL\"]', 'DIFAL ICMS: como calcular passo a passo', 'Veja como calcular DIFAL ICMS, identificar a alíquota interestadual, conferir a alíquota interna, FCP e base com exemplo prático.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04'),
(37, NULL, 'Alíquota interestadual de ICMS: quando usar 4%, 7% ou 12%', 'aliquota-interestadual-icms-4-7-12', 'Entenda quando a alíquota interestadual do ICMS é 4%, 7% ou 12%, como origem e destino influenciam e onde entram os importados.', '<p>Escolher corretamente a alíquota interestadual é uma etapa básica do cálculo do ICMS e do DIFAL. As porcentagens de 4%, 7% e 12% não são opções livres: cada uma depende da origem, do destino e, no caso dos 4%, das características da mercadoria importada previstas em resolução do Senado.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> 7% e 12% dependem principalmente da combinação origem/destino; 4% depende do enquadramento da mercadoria importada. Antes de calcular, confirme se há regra específica, benefício ou exceção.</div><h2>Quando a alíquota interestadual é 12%</h2><p>A Resolução do Senado nº 22/1989 estabelece alíquota interestadual de 12% como regra geral. Isso cobre operações que não entram na regra reduzida de 7% e não estão enquadradas na alíquota de 4% para importados.</p><h2>Quando a alíquota é 7%</h2><p>A alíquota de 7% aplica-se, pela regra da Resolução 22/1989, às operações e prestações realizadas das Regiões Sul e Sudeste destinadas às Regiões Norte, Nordeste e Centro-Oeste e ao Estado do Espírito Santo.</p><h3>Exemplos típicos de 7%</h3><ul><li>São Paulo para Bahia.</li><li>Rio de Janeiro para Goiás.</li><li>Paraná para Pernambuco.</li><li>Santa Catarina para Espírito Santo.</li></ul><p>Esses exemplos servem para visualizar a direção da operação. A classificação fiscal e regras especiais ainda precisam ser consideradas.</p><h2>Quando a alíquota é 4%</h2><p>A Resolução do Senado nº 13/2012 definiu alíquota de 4% para operações interestaduais com determinados bens e mercadorias importados do exterior, inclusive após industrialização quando o conteúdo de importação estiver nas condições previstas pela norma. Existem exceções e critérios técnicos, por isso a simples informação de que o produto é \'importado\' não basta em todos os casos.</p><h2>Tabela mental rápida</h2><ul><li>Regra geral interestadual: 12%.</li><li>Sul/Sudeste → Norte/Nordeste/Centro-Oeste/ES: 7%.</li><li>Mercadoria importada enquadrada na Resolução 13/2012: 4%.</li></ul><h2>Por que origem e destino precisam estar corretos</h2><p>Inverter a direção da operação muda a alíquota. Uma venda de São Paulo para Bahia tende à regra de 7%, mas uma venda da Bahia para São Paulo não usa a mesma lógica reduzida por direção. O sistema deve calcular com base na UF de saída e de destino reais.</p><h2>Alíquota interestadual não é alíquota interna</h2><p>A alíquota interestadual é usada na operação entre estados. A alíquota interna do estado de destino é outro dado e pode variar por produto. No DIFAL, confundir as duas é um dos erros mais graves, porque altera diretamente a diferença calculada.</p><h2>Exemplo no DIFAL</h2><p>Se uma operação SP → BA usa 7% interestadual e o produto possui alíquota interna confirmada de 18% na Bahia, a diferença nominal é de 11 pontos percentuais antes de considerar método de base, FCP e demais particularidades. Se a operação estiver corretamente enquadrada em 4% por importação, a diferença nominal seria maior.</p><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-difal-icms\">Identificar e simular a alíquota</a></div></div><h2>Perguntas frequentes</h2><h3>Toda mercadoria importada usa 4%?</h3><p>Não. A Resolução 13/2012 contém critérios e exceções. O enquadramento deve ser confirmado antes de forçar a alíquota.</p><h3>Venda de SP para ES é 7%?</h3><p>A Resolução 22/1989 inclui o Espírito Santo na regra reduzida para operações originadas no Sul e Sudeste, observadas demais regras da operação.</p><h3>A alíquota interna pode ser 18% em qualquer produto?</h3><p>Não. A alíquota interna depende da legislação estadual e do produto/serviço. Ela não deve ser presumida com base apenas em uma alíquota padrão do estado.</p><h2>Conclusão</h2><p>A alíquota interestadual pode ser automatizada com segurança quando origem, destino e enquadramento da mercadoria estão claros. O restante do cálculo fiscal deve continuar mostrando as premissas, para que o profissional consiga conferir o resultado antes do recolhimento.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://legis.senado.leg.br/norma/586152/publicacao?tipoDocumento=RSF&tipoTexto=ATU\" rel=\"nofollow noopener\" target=\"_blank\">Resolução do Senado 22/1989</a></li><li><a href=\"https://legis.senado.leg.br/norma/586999/publicacao?tipoDocumento=RSF&tipoTexto=ATU\" rel=\"nofollow noopener\" target=\"_blank\">Resolução do Senado 13/2012</a></li></ul>', 3, 'Fiscal e Tributário', 'blog/covers/difal-icms-fcp.png', 'Ilustração explicando alíquotas interestaduais de ICMS de 4%, 7% e 12%', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'alíquota interestadual ICMS', '[\"ICMS 4% 7% 12%\", \"alíquota ICMS interestadual\", \"resolução 22 1989\", \"resolução 13 2012\", \"DIFAL\"]', 'ICMS interestadual: quando usar 4%, 7% ou 12%', 'Entenda quando usar alíquota interestadual de ICMS de 4%, 7% ou 12%, com exemplos de origem e destino e regra para importados.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04'),
(38, NULL, 'FCP no DIFAL: quando aplicar, como calcular e o que conferir', 'fcp-no-difal-quando-aplicar-como-calcular', 'Entenda o FCP no DIFAL, por que ele deve aparecer separado, como calcular o percentual e quais regras estaduais precisam ser confirmadas.', '<p>O Fundo de Combate à Pobreza, normalmente identificado como FCP ou FECP conforme a unidade federativa, pode acrescentar um percentual à carga do ICMS em determinadas operações e produtos. No cálculo do DIFAL, esse valor merece destaque separado porque a existência, a alíquota e a base dependem da legislação do estado de destino.</p><div class=\"alert alert-info\"><strong>Resumo prático:</strong> não aplique um percentual de FCP apenas porque o estado possui fundo. O adicional pode variar por produto, NCM, essencialidade, benefício, operação e período de vigência.</div><h2>O que é FCP</h2><p>O FCP é um adicional vinculado ao ICMS previsto no sistema constitucional e regulamentado pelos estados. Na prática fiscal, ele pode aparecer em operações internas e também em contextos de diferencial de alíquotas, conforme a legislação do destino.</p><h2>FCP e DIFAL são a mesma coisa?</h2><p>Não. O DIFAL representa o diferencial entre cargas do ICMS conforme a regra aplicável. O FCP é um adicional separado. Em uma memória de cálculo bem estruturada, os dois valores aparecem em linhas distintas para que o recolhimento e a conferência não se misturem.</p><h2>Exemplo simples</h2><p>Considere base confirmada de R$ 1.000,00 e FCP de 2%. Em uma simulação simples, o FCP seria R$ 20,00. Se o mesmo cenário tiver R$ 110,00 de DIFAL, o total destinado ao estado, apenas para demonstrar a soma dessas duas parcelas, seria R$ 130,00.</p><h2>Quando o FCP pode mudar</h2><ul><li>Alteração de legislação estadual.</li><li>Mudança de NCM ou enquadramento do produto.</li><li>Produto essencial ou supérfluo com tratamento específico.</li><li>Benefício fiscal, redução de base ou isenção.</li><li>Mudança da data de referência.</li><li>Operação sujeita a regra especial.</li></ul><h2>Como pesquisar a alíquota correta</h2><p>A pesquisa deve partir da legislação oficial do estado de destino e da classificação do produto. Tabelas privadas podem acelerar a triagem, mas a validação final deve considerar a fonte oficial e a vigência. A LC 190/2022 reforçou a necessidade de divulgação estadual de informações relacionadas ao DIFAL.</p><h2>FCP na base simples e em outros métodos</h2><p>A base do FCP pode acompanhar a base da operação ou receber tratamento específico conforme a norma estadual. Por isso, uma calculadora segura deve pedir o percentual e deixar clara a base utilizada, em vez de assumir que qualquer estado usa exatamente o mesmo procedimento.</p><h2>Como documentar o cálculo</h2><ol><li>Registre UF de destino e competência.</li><li>Guarde a NCM ou identificação do produto usada na pesquisa.</li><li>Anote a alíquota interna confirmada.</li><li>Anote a alíquota e a base do FCP.</li><li>Salve o fundamento ou link da legislação estadual consultada.</li><li>Mantenha DIFAL e FCP separados no resultado.</li><li>Revise o recolhimento antes da transmissão ou pagamento.</li></ol><div class=\"card border-primary-subtle bg-primary-subtle my-4\"><div class=\"card-body\"><h2 class=\"h4\">Faça a simulação no Prazzu Tools</h2><p>Use a ferramenta relacionada para conferir os valores com memória de cálculo e premissas visíveis.</p><a class=\"btn btn-primary prazzu-btn-primary\" href=\"/ferramentas/calculadora-difal-icms\">Simular DIFAL e FCP</a></div></div><h2>Perguntas frequentes</h2><h3>FCP é sempre 2%?</h3><p>Não. Percentuais e produtos alcançados variam conforme a legislação estadual. Dois por cento é comum em alguns cenários, mas não deve ser tratado como padrão nacional.</p><h3>Todo produto paga FCP?</h3><p>Não. O alcance depende da legislação do estado e da mercadoria ou serviço.</p><h3>O FCP usa a mesma guia do DIFAL?</h3><p>A forma de recolhimento varia por estado e operação. A conferência do documento e código de receita deve ser feita na regra oficial do destino.</p><h2>Conclusão</h2><p>O FCP é pequeno em percentual, mas relevante em conformidade. Separar a parcela do DIFAL, confirmar a legislação do destino e registrar a fonte evita que uma simulação correta matematicamente seja usada com uma alíquota fiscal inadequada.</p><h2>Fontes oficiais para conferência</h2><ul><li><a href=\"https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp190.htm\" rel=\"nofollow noopener\" target=\"_blank\">LC 190/2022 — informações estaduais e DIFAL</a></li><li><a href=\"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm\" rel=\"nofollow noopener\" target=\"_blank\">Constituição Federal — ICMS e adicional destinado a fundos estaduais</a></li></ul>', 3, 'Fiscal e Tributário', 'blog/covers/difal-icms-fcp.png', 'Ilustração sobre FCP e DIFAL no cálculo do ICMS', 'published', 0, '2026-07-27 17:56:04', '2026-07-27 17:56:04', 'FCP DIFAL', '[\"Fundo de Combate à Pobreza\", \"calculadora FCP\", \"DIFAL e FCP\", \"FCP ICMS\", \"alíquota FCP por estado\"]', 'FCP no DIFAL: quando aplicar e como calcular', 'Veja quando o FCP pode entrar no DIFAL, como calcular o adicional, por que ele deve ficar separado e quais regras estaduais conferir.', NULL, NULL, 1, '2026-07-27 17:56:04', '2026-07-27 17:56:04');

